/* Group G03 mastery bank: The brain and neuropsychology; Social influence; Criminal psychology (optional). Original questions, not copied from past papers. */
(function () {
  'use strict';
  var B = window.MASTERY_BANKS = window.MASTERY_BANKS || {};
  var R = window.Mastery;
  function pick(a) { return a[Math.floor(Math.random() * a.length)]; }
  function rint(lo, hi) { return lo + Math.floor(Math.random() * (hi - lo + 1)); }

  B['PSY-BRN-05'] = { title: "Visual agnosia, prosopagnosia and pre-frontal damage", items: [
    {"skill":"define-agnosia","kind":"mcq","q":"Which statement defines <b>visual agnosia</b>?","options":["The person sees normally but cannot recognise or name objects they look at.","The person cannot see because the eyes no longer send signals to the brain.","The person cannot recognise familiar faces but can name all other objects.","The person can name objects but cannot judge how far away they are."],"answer":0,"why":"In visual agnosia the eyes and basic vision work, but the brain cannot make sense of what is seen, so objects are not recognised or named. It is not blindness."},
    {"skill":"define-prosopagnosia","kind":"mcq","q":"Which statement defines <b>prosopagnosia</b>?","options":["An inability to recognise familiar faces, although other objects can be recognised.","An inability to recognise everyday objects by sight, although faces can still be recognised.","An inability to see anything at all in the left half of the visual field.","An inability to remember new faces because of a poor short-term memory."],"answer":0,"why":"Prosopagnosia, or ‘face blindness’, is a failure to recognise familiar faces, even those of close family, while other objects are still recognised."},
    {"skill":"apply-agnosia","kind":"mcq","q":"Rafi had a stroke. He can see well and can draw a neat copy of his house key, but when he looks at it he cannot say what it is. As soon as he holds it, he says ‘my key’. Which condition does this show?","options":["Visual agnosia, because he can see the object but cannot recognise it by sight.","Prosopagnosia, because he cannot recognise a familiar object that he is looking at.","Blindness, because he cannot name what he is looking at until he touches it.","Damage to the pre-frontal cortex, because he is slow to name the object."],"answer":0,"why":"Seeing and copying the key shows his vision works. Recognising it only by touch is typical of visual agnosia. The problem is with objects, not faces."},
    {"skill":"apply-prosopagnosia","kind":"mcq","q":"Mrs Okoro can name her mug, her phone and her cat, but she does not know her own daughter when they meet in a shop. She knows her as soon as the daughter speaks. Which condition does this show?","options":["Prosopagnosia, because she can recognise objects but not a familiar face.","Visual agnosia, because she cannot recognise a person she is looking at.","Damage to the pre-frontal cortex, because she has lost her sense of judgement.","Blindness, because she needs a voice to know who a person is."],"answer":0,"why":"Objects are recognised normally, but a close family member’s face is not, and the voice is used instead. That pattern is prosopagnosia."},
    {"skill":"not-blindness","kind":"mcq","q":"A student says: ‘Someone with visual agnosia must be blind.’ Which reply is correct?","options":["Wrong, because their eyes and basic vision work but they cannot recognise what they see.","Correct, because they cannot see everyday objects clearly enough to be able to name them.","Wrong, because they can recognise objects by sight but not by touch.","Correct, because the condition always follows damage to the eyes."],"answer":0,"why":"Agnosia is a problem of recognition in the brain, not of seeing. Many people with agnosia can describe or copy shapes, so they are not blind."},
    {"skill":"symptoms-prosopagnosia","kind":"multi","q":"Which of these are <b>signs or effects</b> of prosopagnosia in everyday life? Select all that apply.","options":["Using someone’s voice, hair or clothes to work out who they are","Finding it hard to follow the characters in a film","Not recognising yourself in a photograph","Being unable to name a kettle placed in front of you","Being unable to see shapes or colours"],"answers":[0,1,2],"why":"Prosopagnosia affects faces, so people rely on other clues such as voice, hair and clothes, struggle with films and may not recognise their own photo. Failing to name objects is visual agnosia, and being unable to see is not either condition."},
    {"skill":"symptoms-agnosia","kind":"multi","q":"Which of these might a person with <b>visual agnosia</b> be able to do? Select all that apply.","options":["Copy a drawing of an object they cannot name","Recognise an object by feeling it","Recognise an object from the sound it makes","Name every object on a table just by looking at it","Recognise objects only if they are in the left of vision"],"answers":[0,1,2],"why":"People with visual agnosia can often draw or copy a shape and identify the object by touch or sound, but they cannot name it just by looking. The other two statements do not describe the condition."},
    {"skill":"brain-areas","kind":"mcq","q":"Damage to which part of the brain is linked to prosopagnosia?","options":["The fusiform gyrus in the temporal region, which helps with recognising faces.","The Broca area in the frontal lobe, which controls speech and the production of language.","The motor cortex, which controls voluntary movement.","The cerebellum, which controls balance and posture."],"answer":0,"why":"The fusiform gyrus, in the temporal region, is the area linked to face recognition. Damage there can cause prosopagnosia."},
    {"skill":"brain-areas","kind":"mcq","q":"A scan shows that a patient has damage to the visual areas in the occipital and temporal regions. Which pair of conditions is this damage linked to?","options":["Visual agnosia and prosopagnosia.","Visual agnosia and damage to the pre-frontal cortex.","Prosopagnosia and a hearing problem.","Poor decision-making and emotional blunting."],"answer":0,"why":"Both agnosia and prosopagnosia can result from damage to the visual areas in the occipital and temporal regions. Poor decisions and emotional blunting are linked to the pre-frontal cortex."},
    {"skill":"prefrontal-effects","kind":"mcq","q":"Which is an effect of damage to the <b>pre-frontal cortex</b>?","options":["Poor decision-making and more impulsive behaviour.","Failing to recognise familiar faces.","Failing to name the everyday objects that a person can see clearly.","Losing the ability to see in one eye."],"answer":0,"why":"The pre-frontal cortex helps with planning, judgement and controlling impulses, so damage can lead to poor decisions and impulsive behaviour."},
    {"skill":"apply-prefrontal","kind":"mcq","q":"After a cycling accident that damaged the front of his brain, Dan, once a careful saver, spent his savings on a boat in one afternoon and now shows little feeling when his friends are upset. Which area was most likely damaged?","options":["The pre-frontal cortex, because of the impulsive spending and emotional blunting.","The fusiform gyrus, because he can no longer recognise his friends’ faces.","The occipital region, because he can no longer see well enough to judge the price of anything.","The temporal region, because he can no longer name the objects he buys."],"answer":0,"why":"Impulsive decisions, emotional blunting and a change in personality point to the pre-frontal cortex. Nothing in the story says he cannot recognise faces or objects."},
    {"skill":"apply-prefrontal","kind":"mcq","q":"Ms Hale was always calm and polite. Since a head injury she shouts at colleagues, makes risky bets and does not seem to worry about the results. Which is the best explanation?","options":["Damage to the pre-frontal cortex has changed her judgement, impulse control and personality.","She has visual agnosia, so she cannot recognise the people who she is shouting at in the office.","She has prosopagnosia, so she treats everyone as a stranger.","She is blind, so she cannot see the consequences of her actions."],"answer":0,"why":"Poor judgement, impulsive behaviour and a personality change are effects of pre-frontal damage. The scenario gives no sign of problems recognising objects or faces."},
    {"skill":"prefrontal-effects","kind":"multi","q":"Which of these can result from damage to the pre-frontal cortex? Select all that apply.","options":["Impulsive behaviour","Emotional blunting","A change in personality","Being unable to recognise familiar faces","Being unable to recognise objects by sight"],"answers":[0,1,2],"why":"Impulsiveness, flattened emotion and personality change are linked to the pre-frontal cortex. Face recognition problems are prosopagnosia and object recognition problems are agnosia."},
    {"skill":"agnosia-or-prosop","kind":"mcq","q":"Tala can recognise any face she knows, but when shown a fork, a lamp or a clock she cannot say what they are, although she can describe their shapes. Which condition does she show?","options":["Visual agnosia, because the difficulty is with objects, not faces.","Prosopagnosia, because she cannot recognise things she sees.","Damage to the pre-frontal cortex, because her answers are poor.","Neither, because she can describe the shapes she sees."],"answer":0,"why":"Faces are recognised and objects are not, so it is visual agnosia. Being able to describe the shapes is a known symptom rather than evidence of no condition."},
    {"skill":"agnosia-or-prosop","kind":"mcq","q":"Which piece of evidence in a case study would best support a diagnosis of prosopagnosia <b>rather than</b> visual agnosia?","options":["The patient names a car, a coat and a dog by sight but not the face of his own brother.","The patient names a car, a coat and a dog only after touching them.","The patient cannot name a car, a coat or a dog by sight but still knows the face of his brother.","The patient makes risky decisions and shows little emotion about them."],"answer":0,"why":"Prosopagnosia means faces fail while objects are recognised. Objects failing but faces working is visual agnosia, and risky decisions suggest pre-frontal damage."},
    {"skill":"prosop-everyday","kind":"mcq","q":"Why might someone with prosopagnosia find it hard to follow a film?","options":["They cannot tell the characters apart by their faces, especially when clothes or hair change.","They cannot see the pictures on the screen clearly enough to follow the story as it goes along.","They cannot recognise the objects in each scene.","They cannot remember what happened in earlier scenes."],"answer":0,"why":"Film characters are mainly recognised by face. Someone who cannot recognise faces must rely on clues such as voice or clothes, which can change from scene to scene."},
    {"skill":"prosop-everyday","kind":"mcq","q":"Sam has prosopagnosia. At a party he works out who his friends are by listening for their voices and noticing their jackets. Which is the best description of this?","options":["He is using other clues because he cannot recognise familiar faces.","He is using touch because he cannot recognise familiar objects.","He is using planning skills because his pre-frontal cortex is damaged.","He is using his eyes less because he is partly blind."],"answer":0,"why":"People with prosopagnosia often rely on voice, clothes and hair to identify people because faces do not trigger recognition."},
    {"skill":"agnosia-everyday","kind":"mcq","q":"Which everyday situation is most likely to be a problem for a person with visual agnosia?","options":["Picking out a spoon from a drawer by looking at it.","Remembering the name of a new neighbour.","Saying hello to a friend they have not seen for years.","Keeping to a budget when out shopping."],"answer":0,"why":"A person with visual agnosia sees the spoon but may not recognise what it is by sight. Names and budgets are memory and pre-frontal issues, and recognising a friend’s face is prosopagnosia."},
    {"skill":"precise-effects","kind":"mcq","q":"Which answer to ‘Describe one effect of damage to the pre-frontal cortex’ is the most precise?","options":["A person may act on impulse and make poor decisions without thinking about the risks.","The person’s brain stops working properly.","The person becomes ill and cannot do normal things.","The person may have some kind of problems with their brain and with how it works in daily life."],"answer":0,"why":"Examiners need a specific effect on behaviour. ‘Acts on impulse and makes poor decisions’ is specific. The other answers are vague."},
    {"skill":"precise-effects","kind":"mcq","q":"A tutor writes ‘He is blind to faces’ in a case note about a patient who sees well but cannot recognise people from their faces. Which term does this describe?","options":["Prosopagnosia, which is also called ‘face blindness’.","Visual agnosia, which is also called ‘object blindness’.","Pre-frontal damage, which is also called ‘emotional blindness’.","Occipital blindness, which is the loss of all sight."],"answer":0,"why":"‘Face blindness’ is the everyday name for prosopagnosia. Despite the name, the person is not blind."},
    {"skill":"apply-prosopagnosia","kind":"mcq","q":"Priya looks at a photograph of her class and cannot find herself, although she can name the building, the flag and the school bus in the picture. Which condition might explain this?","options":["Prosopagnosia, because she cannot recognise faces, including her own, but she recognises objects.","Visual agnosia, because she cannot recognise the building, flag and bus that are shown in the photograph.","Damage to the pre-frontal cortex, because she is being careless.","Blindness, because she cannot see the photograph properly."],"answer":0,"why":"Not recognising even her own face, while naming the objects, is a symptom of prosopagnosia."},
    {"skill":"link-evidence","kind":"mcq","q":"Which detail in a scenario is the most useful for deciding between visual agnosia and prosopagnosia?","options":["Whether the person can recognise familiar faces and everyday objects.","Whether the person is male or female.","Whether the person wears glasses.","Whether the person has a good memory for phone numbers and for the days of the week."],"answer":0,"why":"The two conditions differ in what cannot be recognised: objects (agnosia) or faces (prosopagnosia). Method step one is to look at what the person can and cannot recognise."}
  ] };

  B['PSY-SOC-05'] = { title: "The Stanford prison study (Haney, Banks and Zimbardo)", items: [
    {"skill":"aim","kind":"mcq","q":"What was the aim of the Stanford prison study (Haney, Banks and Zimbardo, 1973)?","options":["To see whether brutality in prisons comes from the prison situation or from the personalities of guards and prisoners.","To see whether prisoners obey orders from guards who are dressed as police officers and who carry batons.","To see whether the personalities of guards and prisoners decide how they behave, whatever the prison is like.","To see whether punishment reduces the chance that prisoners will reoffend."],"answer":0,"why":"The study set out to test whether cruelty in prisons is down to the situation or to the people in it. It was not about conformity or reoffending."},
    {"skill":"sample","kind":"num","q":"About 75 men answered the newspaper advert for the Stanford prison study, and 24 were chosen. <b>How many of the volunteers were not chosen?</b>","answer":51,"unit":"","display":"51","why":"75 − 24 = 51 volunteers were not chosen."},
    {"skill":"sample","kind":"mcq","q":"Who took part as guards and prisoners in the Stanford prison study?","options":["Healthy male college students who were randomly allocated to be guards or prisoners.","Male and female volunteers who chose which role they wanted.","Real prison guards and convicted prisoners from a local jail.","Male college students who were picked as guards because they were the most aggressive."],"answer":0,"why":"The 24 chosen were healthy male college students. Random allocation to roles meant any difference in behaviour should come from the role and not from the person’s personality."},
    {"skill":"sample","kind":"mcq","q":"Why was it a strength that the students were <b>randomly allocated</b> to be guards or prisoners?","options":["It makes it more likely that behaviour came from the roles and not from personality differences.","It ensures the results can be generalised to women and to prison staff, as well as to the students.","It stops the participants from knowing that they were part of a psychology study at all.","It guarantees that nobody suffered any psychological harm."],"answer":0,"why":"If roles are assigned by chance, the guards and prisoners should not differ in personality, so cruelty is more likely to be due to the situation. It does not fix generalisability or ethics."},
    {"skill":"procedure","kind":"mcq","q":"Where was the mock prison built, and how did the prisoners begin the study?","options":["In a basement at Stanford University; the prisoners were ‘arrested’ at home by real police.","In a disused jail in California; the prisoners reported to the building by themselves, on time.","In a basement at Stanford University; the prisoners were told to wait in a classroom for the guards.","In a school gym; the prisoners were ‘arrested’ at the university gates."],"answer":0,"why":"The mock prison was set up in a basement at Stanford. The prisoners were arrested at home by real police to make the experience feel realistic."},
    {"skill":"uniform","kind":"mcq","q":"Which describes what the <b>guards</b> wore and carried?","options":["Khaki military-style uniforms, mirrored sunglasses, whistles and batons.","Plain white coveralls with a number on the front and a plastic badge.","Their own clothes with a name badge and a clipboard.","Black police uniforms with handcuffs and a radio."],"answer":0,"why":"Guards wore khaki uniforms and mirrored sunglasses and carried whistles and batons. The numbered smock, stocking cap and ankle chain were for the prisoners."},
    {"skill":"uniform","kind":"mcq","q":"Which describes what the <b>prisoners</b> wore?","options":["A numbered smock, a stocking cap and a chain on one ankle.","Khaki uniforms with mirrored sunglasses.","Their own clothes with a name tag showing their first name.","A grey jumpsuit with a badge showing their surname."],"answer":0,"why":"Prisoners wore numbered smocks, stocking caps and an ankle chain, which made them feel less like individuals."},
    {"skill":"rules","kind":"mcq","q":"Which rule was part of life for the prisoners in the study?","options":["Three supervised toilet visits a day.","Unlimited free time between meals.","Two meals a day, one at each end of the day.","One visiting period each day."],"answer":0,"why":"Prisoners had three meals and three supervised toilet visits a day, two visiting periods a week, scheduled exercise and film time, and three roll-call line-ups a day."},
    {"skill":"rules","kind":"multi","q":"Which of these were rules or routines in the mock prison? Select all that apply.","options":["Three meals a day","Two visiting periods a week","Three roll-call line-ups a day","Two supervised toilet visits a day","Daily visits from family"],"answers":[0,1,2],"why":"The routine was three meals, three supervised toilet visits and three roll-calls a day, with two visiting periods a week. The other two statements get the numbers wrong."},
    {"skill":"stopped","kind":"num","q":"The Stanford prison study was planned to last 14 days but was stopped after 6 days. <b>How many days earlier than planned did it end?</b>","answer":8,"unit":"days","display":"8 days","why":"14 − 6 = 8 days. The study was planned for 14 days (two weeks) but stopped after 6, so it ended 8 days early."},
    {"skill":"stopped","kind":"mcq","q":"Why was the study stopped after six days?","options":["Some guards had become cruel and several prisoners were showing severe emotional distress.","The guards and prisoners had all agreed together that the study was no longer realistic enough.","The prisoners had managed to escape from the basement.","The police insisted that the study should end because it was being held without permission from them."],"answer":0,"why":"Planned for two weeks, it ended early because of the guards’ cruelty and the prisoners’ distress. It was ended for ethical reasons, not because results were complete."},
    {"skill":"conclusion","kind":"mcq","q":"What did Haney, Banks and Zimbardo conclude?","options":["Behaviour was strongly shaped by the situation and the roles, helped by deindividuation.","Behaviour in prison is mainly caused by the personalities that the people bring with them to it.","Behaviour is mainly caused by the fear of punishment from authority.","Behaviour does not change when people are placed in a new role."],"answer":0,"why":"They concluded that the prison situation, the roles and the loss of personal identity (deindividuation) changed how ordinary young men behaved."},
    {"skill":"deindividuation","kind":"mcq","q":"In this study, how did uniforms help to produce deindividuation?","options":["Identical clothes and anonymity reduced the sense of personal identity.","Uniforms made the guards feel they must obey an order from someone in charge.","Uniforms made the prisoners feel more important than the guards.","Uniforms made everyone feel they were being watched by the researchers."],"answer":0,"why":"Deindividuation is a loss of personal identity. Matching uniforms, sunglasses and numbers made the participants feel anonymous and less responsible for their actions."},
    {"skill":"apply-uniform","kind":"mcq","q":"A drama teacher gives all her pupils identical grey masks and robes for a play about a courtroom. During rehearsal, some pupils start to shout and push others. Which finding from the Stanford prison study best explains this?","options":["Wearing the same clothes and hiding identity can lead to deindividuation and changed behaviour.","Following a direct order from a person with authority leads ordinary people to behave with cruelty.","Giving rewards for good behaviour makes it more likely to be repeated.","Matching the answers of the majority group reduces uncertainty."],"answer":0,"why":"Identical masks and robes hide personal identity, as the uniforms did at Stanford. The pupils’ behaviour changes because they feel anonymous in their roles."},
    {"skill":"apply-role","kind":"mcq","q":"At a summer camp, older teenagers are given a yellow ‘supervisor’ vest and sunglasses and told to monitor younger campers. After a week, several supervisors start to order the campers about harshly. According to the Stanford prison study, why might this happen?","options":["The uniform and the role of authority can change how people act, even if they are not cruel by nature.","Teenagers who are chosen to be supervisors are always aggressive by personality, whatever role they have.","The younger campers are copying an aggressive model they have seen on television.","Seeing others rewarded makes the supervisors copy their behaviour."],"answer":0,"why":"The study found that a uniform and a position of power changed behaviour in ordinary people. The explanation is the situation and role, not a fixed personality."},
    {"skill":"apply-role","kind":"mcq","q":"A shop assistant is moved to a job in which she wears a name badge and her own clothes instead of a uniform and mask. A manager says people behave less rudely when they are easy to identify. Which idea from the study fits this?","options":["Being identifiable reduces deindividuation, so people feel more responsible for their behaviour.","Being identifiable increases conformity because the group sets the standard for how people behave.","Being identifiable increases the effect of vicarious reinforcement.","Being identifiable means personality alone decides behaviour."],"answer":0,"why":"Deindividuation comes from anonymity. If people are easier to identify they feel more personally responsible, which is the opposite of the effect of anonymous uniforms."},
    {"skill":"weakness-sample","kind":"mcq","q":"Which is a weakness of the sample in the Stanford prison study?","options":["It was only young male students, so the findings may not apply to women or other groups.","It was a very large sample, so the pattern was too varied to be clear.","It was made up of experienced guards, so it was biased.","It was randomly selected from the whole population of the USA."],"answer":0,"why":"Only 24 healthy male college students were chosen, so it is difficult to generalise to women or people of other ages and backgrounds."},
    {"skill":"weakness-setting","kind":"mcq","q":"Which is a weakness of the Stanford prison study as a way to explain real prison behaviour?","options":["It was an artificial setting, so the participants may have acted out roles they thought were expected.","It took place in a real prison, so the results were too realistic to be useful.","It had no control over who was a guard and who was a prisoner.","It only measured what the participants said, not what they did."],"answer":0,"why":"A mock prison in a basement is less realistic than a real prison, and the participants may have shown demand characteristics by acting the parts. This reduces how far results apply to real life."},
    {"skill":"weakness-ethics","kind":"mcq","q":"Which is a valid ethical criticism of the Stanford prison study?","options":["Prisoners suffered severe emotional distress, so participants were not protected from psychological harm.","The participants were not paid for taking part, so it was not fair.","The researchers published the results, so nobody had privacy.","The participants had signed consent forms, so there was nothing to criticise."],"answer":0,"why":"Several prisoners became severely distressed and the study continued for six days. Protection from harm is the key ethical point."},
    {"skill":"strength","kind":"mcq","q":"Which is a strength of the Stanford prison study?","options":["It showed how powerful a situation can be, with ordinary people behaving cruelly in a role.","It had perfect ecological validity because it took place in a real prison with real prison guards.","It used a large, varied sample of men and women.","It was ethically sound because everyone was fully protected."],"answer":0,"why":"Random allocation and ordinary students suggest the situation changed behaviour. The other options are wrong: it was a mock prison, a small male sample and ethically criticised."},
    {"skill":"common-error","kind":"mcq","q":"A student writes: ‘The Stanford prison study lasted two weeks.’ What is wrong with this?","options":["Two weeks was the plan, but it was stopped after six days.","It lasted one week, which was the plan.","It lasted two weeks and ended when all prisoners had been released.","It lasted six weeks and was stopped by the university."],"answer":0,"why":"It was planned for two weeks but was stopped after six days because of the guards’ cruelty and the prisoners’ distress."},
    {"skill":"apply-weakness","kind":"mcq","q":"A magazine says the Stanford prison study proves that all prison guards in the UK become cruel. Which is the best criticism?","options":["The sample was American male students in a mock prison, so it cannot be generalised to all real guards.","The guards were not given uniforms or sunglasses, so the study did not really test the situation at all.","The guards were chosen for their cruelty, so the study cannot be trusted.","The study only lasted for two weeks, so it could not show anything about cruelty in the prison."],"answer":0,"why":"Claiming ‘all UK guards’ goes beyond a small group of American male students acting in a mock prison. The study did use uniforms and random allocation."}
  ] };

  B['PSY-SOC-01'] = { title: "Why people obey - and how to stop blind obedience", items: [
    {"skill":"define-obedience","kind":"mcq","q":"Which statement best defines <b>obedience</b>?","options":["Carrying out a direct order from someone you see as having legitimate authority.","Changing your behaviour or your opinions so that they match the majority view of a group.","Copying the behaviour of a role model you look up to.","Losing your sense of personal identity when you are part of a large crowd of people."],"answer":0,"why":"Obedience involves an order from an authority figure. Matching a group is conformity, copying a model is social learning and losing identity is deindividuation."},
    {"skill":"obedience-vs-conformity","kind":"mcq","q":"Which situation is an example of <b>obedience</b> and not conformity?","options":["A cook peels the vegetables because the head chef orders her to.","A cook starts wearing the same style of apron as the other cooks.","A cook agrees with the group that the soup is too salty, though she thinks it is fine.","A cook copies the way a famous TV chef holds a knife."],"answer":0,"why":"Obedience is a response to a direct order from someone in authority. The other situations involve peers or a model, with no order given."},
    {"skill":"milgram-1963","kind":"num","q":"In Milgram’s 1963 study, 40 American men acted as ‘teachers’ and 65% went all the way to 450 volts. <b>How many of the 40 men went to 450 volts?</b>","answer":26,"unit":"men","display":"26 men","why":"65% of 40 = 0.65 × 40 = 26 men."},
    {"skill":"milgram-variation-calc","kind":"num","q":"In the Milgram variation where another person pressed the switch, 40 participants took part and 92.5% went all the way to 450 volts. <b>How many of the 40 went to 450 volts?</b>","answer":37,"unit":"participants","display":"37 participants","why":"92.5% of 40 = 0.925 × 40 = 37 participants."},
    {"skill":"milgram-1963","kind":"mcq","q":"Which result from Milgram’s 1963 study is correct?","options":["All of the teachers gave shocks of at least 300 volts.","Only a few of the teachers gave shocks above 150 volts.","Fewer than half of the teachers gave shocks of 300 volts.","All of the teachers refused to give shocks of more than 150 volts."],"answer":0,"why":"Every one of the 40 teachers went to at least 300 volts, and 65% went to the maximum of 450 volts. Ordinary people obeyed far more than expected."},
    {"skill":"situation-location","kind":"mcq","q":"In Milgram’s variations, what happened to obedience when the study was moved from Yale University to a run-down office building?","options":["It fell, because the setting seemed to have less authority.","It rose, because the teachers were less worried about being watched.","It stayed exactly the same, because the order was the same.","It fell to 0%, because nobody would obey in a run-down office."],"answer":0,"why":"A less prestigious setting reduced obedience, which shows how the situation and the legitimacy of the authority affect obedience. It did not fall to zero."},
    {"skill":"situation-telephone","kind":"mcq","q":"Obedience fell when the experimenter gave orders by <b>telephone</b>. What does this show about obedience?","options":["It is lower when the authority figure is not physically present.","It is higher when the authority figure is out of sight and cannot check what is happening.","It is unaffected by where the authority figure is.","It depends on the personality of the teacher and has nothing to do with the situation."],"answer":0,"why":"Without the authority figure in the room, the teachers felt more able to disobey. Distance between authority and the person reduces obedience."},
    {"skill":"situation-proximity","kind":"mcq","q":"In Milgram’s variations, obedience was lower when the teacher was <b>close</b> to the learner. What is the best explanation?","options":["Seeing the learner’s suffering made it harder to carry on.","The experimenter had less authority in the room when the learner was sitting close to the teacher.","The teachers felt they were part of a majority.","The teachers wanted to be rewarded for helping."],"answer":0,"why":"Closeness to the victim made the harm more obvious and personal, so fewer people kept obeying."},
    {"skill":"situation-peers","kind":"mcq","q":"In one Milgram variation, two other ‘teachers’ refused to continue. What happened to obedience?","options":["It fell sharply, to 10%.","It stayed the same, at 65%.","It rose, to 92.5%.","It fell slightly, to 50%."],"answer":0,"why":"When two peers disobeyed, only 10% of participants went to the end. Disobedient role models make it easier to resist."},
    {"skill":"situation-peers","kind":"mcq","q":"In another variation, the participant was allowed to let someone else press the switch. What was the level of obedience?","options":["92.5%, because responsibility for the shock was passed to someone else.","10%, because the participant was no longer in charge.","65%, because the situation was exactly the same as it had been in the first study.","40%, because the participant was less sure of the order."],"answer":0,"why":"Obedience rose to 92.5% when someone else delivered the shocks. People are more willing to obey when they do not feel personally responsible."},
    {"skill":"uniform-bickman","kind":"mcq","q":"Bickman (1974) found that people obeyed a man dressed as a guard more than the same man in ordinary clothes. What does this suggest?","options":["A uniform is a sign of authority and raises obedience.","A uniform makes people feel anonymous and so they disobey.","A uniform reduces obedience because people distrust it.","A uniform has no effect because personality decides obedience."],"answer":0,"why":"A guard’s uniform signals legitimate authority, so more people followed the instructions. The situation matters, not just personality."},
    {"skill":"apply-uniform","kind":"mcq","q":"A man wearing a high-visibility vest and a lanyard tells shoppers to leave a car park through a side exit. Almost everyone does. Which finding explains this best?","options":["People obey those who look like authority figures, as in Bickman’s uniform study.","People obey when two peers refuse to carry on, as in one of the Milgram variations.","People obey because they have an internal locus of control.","People obey when the setting is a run-down office building, as in one of Milgram’s variations."],"answer":0,"why":"The vest and lanyard make the man look as if he has authority, so people follow his instruction, as Bickman’s guard uniform did."},
    {"skill":"personality-authoritarian","kind":"mcq","q":"Which person is most likely to be highly obedient, according to the authoritarian personality (Adorno et al., 1950)?","options":["Someone who respects authority and likes clear rules.","Someone who enjoys questioning orders and breaking rules.","Someone who likes to work out their own decisions.","Someone who believes outcomes are controlled by their own effort."],"answer":0,"why":"Adorno and colleagues described authoritarian personalities as respectful of authority, fond of rules and more likely to obey."},
    {"skill":"personality-loc","kind":"mcq","q":"Which person is more likely to <b>resist</b> obeying an unfair order?","options":["Someone with an internal locus of control, who believes they are in charge of what happens to them.","Someone with an external locus of control, who believes luck decides what happens to them.","Someone with an authoritarian personality, who respects those in charge.","Someone who has a very strong need to please other people and who wants to be liked by all of them."],"answer":0,"why":"People with an internal locus of control take responsibility for their actions and are more likely to resist unfair orders. Those with an authoritarian personality tend to obey."},
    {"skill":"factors-raise","kind":"multi","q":"Which factors would <b>increase</b> obedience? Select all that apply.","options":["The person giving the order wears a uniform","The person obeying is not the one who carries out the final act","The person obeying has an authoritarian personality","Two other people refuse to carry on","The orders are given over the telephone"],"answers":[0,1,2],"why":"A uniform, shared responsibility and an authoritarian personality all raise obedience. Disobedient peers and orders given by telephone reduce it."},
    {"skill":"factors-lower","kind":"multi","q":"Which factors would <b>decrease</b> obedience? Select all that apply.","options":["The order is given from a distance","Other people refuse to carry on","The setting seems low in status","The person giving the order wears a uniform","Someone else will press the switch for you"],"answers":[0,1,2],"why":"Distance, disobedient peers and a low-status setting reduce obedience. A uniform and passing on responsibility raise it."},
    {"skill":"prevent-roles","kind":"mcq","q":"A hospital wants staff to question unsafe orders. Which method of preventing blind obedience, with its justification, fits best?","options":["Show staff a colleague who refuses an unsafe order, because disobedient peers cut obedience in Milgram’s study.","Ask the senior doctor to wear a uniform, because uniforms lower obedience in Bickman’s study.","Make the manager give orders face to face, because obedience falls when the authority is close.","Pass the responsibility on to the senior doctor, because this lowers obedience in Milgram’s study."],"answer":0,"why":"A disobedient role model lowered obedience to 10% in Milgram’s variation. The other options would raise obedience or contradict the findings."},
    {"skill":"prevent-distance","kind":"mcq","q":"A manager tells a call-centre worker to mislead customers. The worker is given the option of taking orders by email rather than in a meeting. Which prevention method does this relate to?","options":["Putting distance between the authority figure and the person, as in Milgram’s telephone variation.","Using a role model who refuses to carry on, as in Milgram’s peer rebellion variation with two peers.","Education about obedience, as in a talk to staff about findings from research studies.","Taking personal responsibility, as in a worker who refuses to press the switch."],"answer":0,"why":"Reducing the authority’s physical presence lowered obedience in Milgram’s telephone variation, so distance can help stop blind obedience."},
    {"skill":"prevent-responsibility","kind":"mcq","q":"Ivan is told by his team captain to injure an opponent. He thinks: ‘If I do this, I am the one who is responsible, not the captain.’ Which way of preventing blind obedience is this?","options":["Taking personal responsibility for his own actions.","Following a role model who is disobedient, because other people refuse to do what is asked.","Moving further away from the authority figure so that the order is not heard.","Being educated about obedience research."],"answer":0,"why":"Accepting that you are personally responsible makes you less likely to obey harmful orders. In Milgram’s study, obedience rose when someone else took on the responsibility."},
    {"skill":"prevent-education","kind":"mcq","q":"A school runs an assembly about how ordinary people in Milgram’s study obeyed harmful orders. Which way of preventing blind obedience is this?","options":["Education about obedience research.","Using a disobedient role model.","Putting distance between the authority and the person.","Giving the person a uniform to wear."],"answer":0,"why":"Teaching people about what influences obedience helps them recognise and resist it. A uniform would increase obedience."},
    {"skill":"apply-two-ways","kind":"mcq","q":"A sports coach tells his team to cheat by pretending to be injured. Which pair gives two <b>different</b> ways of preventing blind obedience?","options":["Following a player who refuses to obey; learning about Milgram’s findings.","A player disobeys the coach; another player also disobeys the coach in the same way.","A player refuses to take part; the next player also says no to the coach.","A player ignores the coach; a second player ignores the coach too."],"answer":0,"why":"Role models and education are two separate methods. The other pairs give the same idea twice, such as ‘disobeying’ and ‘refusing’."},
    {"skill":"common-error","kind":"mcq","q":"A student answers: ‘To stop blind obedience, you should follow what the rest of your team do.’ What is wrong with this?","options":["That describes conformity to a group, not resisting an order from an authority.","That describes personality, which is fixed from birth and cannot be changed by experience.","That describes an internal locus of control.","That describes obedience to a uniform, because the people in the team all wear one."],"answer":0,"why":"Obedience is about orders from an authority figure. Following your team is conformity, and doing so does not stop blind obedience."}
  ] };

  B['PSY-SOC-02'] = { title: "Conformity to majority influence", items: [
    {"skill":"define-conformity","kind":"mcq","q":"Which statement best defines <b>conformity</b>?","options":["Changing your behaviour or opinions so that they match the majority of a group.","Carrying out a direct order from a person who has the legitimate authority to give it.","Losing your sense of personal identity when you are in a crowd of people who are all anonymous.","Copying the behaviour of a single role model you admire."],"answer":0,"why":"Conformity is yielding to the majority. No order is given, which separates it from obedience."},
    {"skill":"conformity-vs-obedience","kind":"mcq","q":"Which is an example of <b>conformity</b>?","options":["Jo says she loves a band because all her friends say so, though she finds the songs dull.","Jo hands in her phone because the head teacher orders her to, and she does it straight away.","Jo stops at the red light because a police officer holds up a hand to tell the traffic to stop.","Jo copies a dance she saw one celebrity perform on TV."],"answer":0,"why":"Conformity means changing to match a group when no order has been given. The other examples involve an order or a single model."},
    {"skill":"asch-procedure","kind":"mcq","q":"In Asch’s (1951) study, what did the participants have to do?","options":["Judge which of three lines matched a standard line while confederates gave wrong answers.","Give electric shocks to a learner who answered a quiz wrongly, when told to by a researcher.","Watch an adult hit a doll and then play with the toys in a room next door to the adult.","Play the role of guard or prisoner in a mock prison."],"answer":0,"why":"Male students were asked to match line lengths while confederates gave the same wrong answers on certain trials to see whether the real participant would go along with them."},
    {"skill":"asch-results","kind":"mcq","q":"Which result from Asch’s study is correct?","options":["About a third of the answers on critical trials conformed, and about three-quarters of participants conformed at least once.","About three-quarters of the answers on critical trials conformed, and about a third of participants conformed at least once.","Hardly anyone conformed, with only about 5% of answers going along with the majority.","About two-thirds of participants conformed on every critical trial."],"answer":0,"why":"On critical trials 32% of answers conformed, and about 75% of the participants conformed at least once."},
    {"skill":"asch-results","kind":"num","q":"In a classroom replication of Asch’s study, 40 students each faced 12 critical trials. Altogether, 150 of the 480 answers were wrong in line with the majority. <b>What percentage of answers conformed?</b> Give your answer to the nearest 1%.","answer":31,"unit":"%","display":"31 %","why":"150 ÷ 480 = 0.3125, so 31.25%. To the nearest 1% this is 31%.","tol":0.5},
    { skill: "data-percentage", gen: function () {
        var n = pick([20, 40, 50]), pc = pick([10, 20, 30, 40, 60, 70]);
        var k = n * pc / 100;
        return { kind: 'num', q: "A researcher tests conformity with " + n + " students. In the unanimous-majority condition " + pc + "% of the students gave the wrong answer. <b>How many students conformed?</b>",
          answer: k, unit: 'students', display: k + ' students', why: pc + "% of " + n + " = " + pc + " ÷ 100 × " + n + " = " + k + " students." };
    } },
    { skill: "data-compare", gen: function () {
        var a = rint(8, 14), b = rint(30, 38), c = b + rint(0, 3);
        var names = pick([["Aziz", "Maya"], ["Kofi", "Lena"], ["Dev", "Rosa"]]);
        return { kind: 'num', q: "A psychologist measured conformity (% of critical answers that matched the group) at different group sizes.<table class=\"mc-table\"><tr><th>Number in the majority</th><th>1</th><th>3</th><th>6</th></tr><tr><td>Conformity (%)</td><td>" + a + "</td><td>" + b + "</td><td>" + c + "</td></tr></table><b>How many percentage points higher was conformity with a majority of 3 than with a majority of 1?</b>",
          answer: b - a, unit: 'percentage points', display: (b - a) + ' percentage points', why: "Compare the two conditions: " + b + " − " + a + " = " + (b - a) + " percentage points. A majority of 3 raised conformity much more than adding people after that." };
    } },
    { skill: "data-conclude", gen: function () {
        var a = rint(5, 12), b = rint(30, 40), c = b + rint(1, 3);
        return { kind: 'mcq', q: "A psychologist measured conformity (% of critical answers that matched the group) at different group sizes.<table class=\"mc-table\"><tr><th>Number in the majority</th><th>1</th><th>3</th><th>8</th></tr><tr><td>Conformity (%)</td><td>" + a + "</td><td>" + b + "</td><td>" + c + "</td></tr></table>Which conclusion is best supported by the figures?",
          options: ["Conformity rose from " + a + "% to " + b + "% as the majority grew to 3, but a majority of 8 added very little (" + c + "%).",
                    "Conformity rose by the same amount for every extra person in the majority.",
                    "Conformity was highest when the majority was one person (" + a + "%).",
                    "Group size had no effect on conformity."],
          answer: 0, why: "Compare the conditions and quote the numbers: " + a + "% → " + b + "% from 1 to 3, then only " + b + "% → " + c + "% from 3 to 8. Group size matters up to about three or four people." };
    } },
    { skill: "data-task", gen: function () {
        var easy = rint(5, 15), hard = easy + rint(20, 30);
        return { kind: 'mcq', q: "Class 9A did an easy quiz and then a hard quiz with a confederate majority giving wrong answers. The table shows how many answers matched the wrong majority.<table class=\"mc-table\"><tr><th>Quiz</th><th>Easy</th><th>Hard</th></tr><tr><td>Conformity (%)</td><td>" + easy + "</td><td>" + hard + "</td></tr></table>Which explanation fits the figures?",
          options: ["Students conformed more on the hard quiz (" + hard + "% compared with " + easy + "%) because they were less sure and relied on the group for the answer.",
                    "Students conformed more on the easy quiz (" + easy + "% compared with " + hard + "%) because they were more confident in the majority.",
                    "Students conformed equally on both quizzes because the majority was the same size.",
                    "Students obeyed the confederates on the hard quiz because they were given an order."],
          answer: 0, why: "Hard or ambiguous tasks increase conformity because people look to others for the answer (informational influence). Compare the figures: " + hard + "% is higher than " + easy + "%." };
    } },
    {"skill":"situation-unanimity","kind":"mcq","q":"Asch found that conformity fell sharply when one confederate gave the correct answer. What does this show?","options":["A unanimous majority increases conformity, and one dissenter who agrees with the participant reduces it.","A majority of three people is the largest group that has any effect on how participants answer.","Participants conform more when they have an internal locus of control than an external one, in any task.","Participants only conform when the task is very easy."],"answer":0,"why":"When the group is no longer unanimous, the participant feels able to give their own answer, so conformity drops."},
    {"skill":"apply-unanimity","kind":"mcq","q":"Four friends all say a new film is brilliant. Mina disagrees but says nothing. Later, a fifth friend says she thought the film was awful and Mina agrees with her. Which factor does this show reducing conformity?","options":["One dissenter who agrees with her, breaking the unanimity of the majority.","A task that is difficult and unclear, which makes her unsure of what to say.","A large group of ten or more people, who all agree with each other.","An external locus of control, which makes people feel luck decides things."],"answer":0,"why":"A single person who disagrees with the majority and agrees with the participant makes it easier to resist the group."},
    {"skill":"group-size","kind":"mcq","q":"According to research into conformity, what is the effect of group size?","options":["Conformity increases up to about three or four people, with little extra effect after that.","Conformity keeps on increasing with every extra person who is added to the majority group.","Conformity is highest with one other person present and then falls steadily after that.","Conformity is the same whatever the size of the group."],"answer":0,"why":"Adding people to the majority raises conformity up to around three or four, then it levels off."},
    {"skill":"apply-group-size","kind":"mcq","q":"A school council of 3 pupils persuades a new pupil to vote for its plan. The council then grows to 10 pupils. Based on research, what is likely to happen to the new pupil’s conformity?","options":["It will rise very little, because conformity levels off after three or four people.","It will almost double, because every extra person who joins adds the same amount of pressure.","It will fall, because a bigger group seems less united.","It will fall to zero, because the group is too large to influence her."],"answer":0,"why":"Growing from 3 to 10 adds little because group size matters only up to about three or four."},
    {"skill":"task-difficulty","kind":"mcq","q":"Why does a harder or more ambiguous task increase conformity?","options":["People are unsure of the answer and look to the group for information.","People are given an order by an authority figure and they are afraid to disobey it.","People feel anonymous and lose their sense of identity.","People have already seen a role model reward the group."],"answer":0,"why":"This is informational influence: when you are unsure you use other people’s answers as evidence of what is correct."},
    {"skill":"apply-task","kind":"mcq","q":"Leo has to guess the weight of a pumpkin at a fair. He has no idea, so he copies the average of the people who guessed before him. Which factor explains this?","options":["The task is hard to judge, so he relies on the group for information.","He has an internal locus of control.","He was ordered to copy the average by an authority figure who was running the stall.","The group is unanimous and he fears being laughed at."],"answer":0,"why":"With a difficult, ambiguous task people depend on others’ answers, which raises conformity. There is no order and no sign of social pressure here."},
    {"skill":"personality-loc","kind":"mcq","q":"According to Rotter (1966), which person is more likely to conform?","options":["Someone with an external locus of control, who thinks events are controlled by outside forces.","Someone with an internal locus of control, who thinks they control what happens in their life.","Someone with high self-esteem, who feels very confident in their own opinions and abilities.","Someone who prefers to work alone and rarely joins groups."],"answer":0,"why":"People with an external locus of control are more likely to conform. People with an internal locus of control or high self-esteem conform less."},
    {"skill":"apply-personality","kind":"mcq","q":"Two students are asked to give an opinion in a group where everyone else has agreed. Nia believes her own effort decides her results and is very confident. Ravi thinks luck decides most things in his life. Who is more likely to conform, and why?","options":["Ravi, because an external locus of control makes conformity more likely.","Nia, because an internal locus of control makes conformity more likely.","Nia, because high self-esteem makes conformity more likely.","Neither, because personality never affects conformity."],"answer":0,"why":"Ravi has an external locus of control and is more likely to conform. Nia’s internal locus of control and confidence make her less likely to."},
    {"skill":"personality-factors","kind":"multi","q":"Which of these are linked to <b>lower</b> conformity? Select all that apply.","options":["An internal locus of control","High self-esteem","An external locus of control","A difficult task","A unanimous majority"],"answers":[0,1],"why":"Internal locus of control and high self-esteem are linked to less conformity. An external locus of control, a difficult task and a unanimous majority all raise conformity."},
    {"skill":"culture","kind":"mcq","q":"According to Bond and Smith (1996), which people tend to conform more?","options":["People from collectivist cultures, which value group harmony.","People from individualist cultures, which value personal choice.","People from every culture conform equally.","People from cultures with a high level of self-esteem."],"answer":0,"why":"Bond and Smith found higher conformity in collectivist cultures than individualist ones."},
    {"skill":"apply-culture","kind":"mcq","q":"Researchers repeat a line-judging task in two countries. In Country X people are brought up to put the needs of the group first. In Country Y people are brought up to value independence. Which result is most likely?","options":["More conformity in Country X, because it is a collectivist culture.","More conformity in Country Y, because it is an individualist culture.","No difference, because culture does not affect conformity.","More conformity in Country Y, because people have an external locus of control."],"answer":0,"why":"Collectivist cultures tend to show higher conformity, as in Bond and Smith’s findings."},
    {"skill":"common-error","kind":"mcq","q":"A student is asked for a factor affecting conformity and writes: ‘In Asch’s study, students looked at lines and a few of them gave wrong answers.’ Why would this not earn full credit?","options":["It describes the study but does not name a factor such as unanimity, group size or task difficulty.","It names a factor correctly but it does not explain how the factor changes conformity.","It confuses conformity with obedience.","It uses data from the study but it does not compare two different conditions with each other."],"answer":0,"why":"A factor must be named precisely and explained, such as ‘a unanimous majority raises conformity’. Description of the procedure is not a factor."},
    {"skill": "apply-sample", "kind": "mcq", "q": "A researcher repeats Asch’s line-judging task with a unanimous group of confederates. Which participant group did Asch (1951) originally use?", "options": ["Male students, who judged line lengths alongside confederates.", "Female nurses, who judged weights alongside colleagues.", "Mixed-age shoppers, who judged prices alongside staff.", "Child pupils, who judged colours alongside classmates."], "answer": 0, "why": "Asch’s participants were male students who matched line lengths while confederates gave wrong answers on critical trials."},
    {"skill": "apply-dissenter", "kind": "mcq", "q": "In a replication, 6 confederates all give the same wrong answer in one condition, and in another condition one confederate gives the correct answer. Which prediction is best?", "options": ["Conformity will be lower in the second condition, because the majority is no longer unanimous.", "Conformity will be lower in the first condition, because the group is bigger.", "Conformity will be the same in both conditions, because six people are still present.", "Conformity will be higher in the second condition, because the answers are mixed."], "answer": 0, "why": "A dissenter who agrees with the participant reduces conformity sharply, even when the rest of the group is large."}
  ] };

  B['PSY-CRI-06'] = { title: "Charlton et al. (2000): TV comes to St Helena", items: [
    {"skill":"context","kind":"mcq","q":"Why was St Helena a suitable place for Charlton et al. (2000) to study the effects of television?","options":["It was a remote island that received broadcast TV for the first time in 1995.","It was a large city where children watched a lot of violent TV for years.","It was an island where TV was banned so children could be compared with a TV group.","It was a school where researchers could control which programmes were shown."],"answer":0,"why":"Because broadcast TV arrived on St Helena for the first time in 1995, researchers could look at children’s behaviour before and after TV was introduced."},
    {"skill":"method","kind":"mcq","q":"Which best describes the method used by Charlton et al.?","options":["A natural experiment using observation of children’s free play before and after TV arrived.","A laboratory experiment in which children watched the TV programmes that the researchers had chosen for them.","A questionnaire survey of parents about the TV their children watched.","A case study of one child who watched a lot of TV."],"answer":0,"why":"The researchers did not create the change: TV arrived naturally. They video recorded free play in school playgrounds and coded the behaviour."},
    {"skill":"sample","kind":"mcq","q":"Which statement describes the sample in Charlton et al.’s study?","options":["Children aged around 3 to 8 years, selected randomly.","Teenagers aged 13 to 17 who volunteered by answering an advert.","Adults aged 18 to 30 who lived on the island.","Children aged around 3 to 8 who were chosen because they were already aggressive."],"answer":0,"why":"The children observed were aged around 3 to 8 years and were selected randomly from the community."},
    {"skill":"behaviours","kind":"mcq","q":"What types of behaviour did Charlton et al. code from the video recordings?","options":["Pro-social and antisocial acts in the children’s free play.","Only the total number of hours of TV that was watched by each child in the study each week.","Only the aggressive acts that happened during lessons.","How well the children copied scenes from TV programmes."],"answer":0,"why":"Observers coded the children’s acts of pro-social behaviour and antisocial behaviour in school playgrounds, before and after TV."},
    {"skill":"findings","kind":"mcq","q":"What was the main finding of Charlton et al. (2000)?","options":["There was little overall change in antisocial or pro-social behaviour after TV arrived.","Antisocial behaviour increased greatly after TV arrived.","Pro-social behaviour fell sharply and antisocial behaviour doubled once television had arrived.","Girls became more aggressive than boys once they had seen TV."],"answer":0,"why":"The study found little overall change in the children’s behaviour after TV arrived, so it did not show that TV violence increased aggression."},
    {"skill":"findings-gender","kind":"mcq","q":"What did Charlton et al. find about differences between boys and girls?","options":["Boys showed many more antisocial acts than girls, and this was not linked to TV.","Girls showed many more antisocial acts than boys because of TV.","Boys and girls behaved in exactly the same way both before and after TV.","Boys became less antisocial after TV arrived, but girls became a lot more antisocial than before."],"answer":0,"why":"Boys were much more antisocial than girls, but this difference was not caused by the arrival of TV."},
    {"skill":"conclusion","kind":"mcq","q":"What did Charlton et al. conclude?","options":["TV violence did not appear to increase aggression; community supervision may have protected children.","TV violence causes aggression because children copy it.","TV has no effect on any child anywhere in the world.","Children are only ever aggressive if they are boys who watch a lot of violence on TV."],"answer":0,"why":"The researchers suggested that close family, school and community supervision may explain why there was no increase in aggression."},
    {"skill":"explanation","kind":"mcq","q":"Which is the explanation Charlton et al. gave for finding little effect of TV?","options":["A close community with supervision from family and school may have protected children.","The children did not understand any of the television programmes that were broadcast on the island.","The programmes shown on the island contained no violence.","The children could not get a signal in their homes."],"answer":0,"why":"The small, close community means adults know the children and supervise them, which may reduce the influence of TV."},
    {"skill":"apply-community","kind":"mcq","q":"A village of 400 people has only recently got a satellite channel. A parent says: ‘Everyone in our village knows each other and teachers and neighbours watch the children closely, so violent shows won’t make them aggressive.’ Which study supports this view?","options":["Charlton et al. (2000), because community supervision may have protected the children.","Bandura, Ross and Ross (1961), because children copy adults they see being aggressive.","Haney, Banks and Zimbardo (1973), because roles change behaviour.","Milgram (1963), because people obey authority figures."],"answer":0,"why":"The St Helena study found no increase in aggression after TV arrived, and suggested that close community supervision may have been the reason."},
    {"skill":"apply-gender","kind":"mcq","q":"On a small island, a teacher notes that in the school playground the boys are much more likely than the girls to push and shout, both before and after the first TV arrived. Which finding from Charlton et al. fits this?","options":["Boys were much more antisocial than girls, and this was not linked to TV.","Girls were more antisocial than boys after TV arrived.","Antisocial acts in boys rose sharply after TV arrived.","Pro-social acts were greater in boys than in girls after TV had arrived on the island."],"answer":0,"why":"The gap between boys and girls was already there and was not caused by TV."},
    {"skill":"apply-tv","kind":"mcq","q":"A newspaper says: ‘Psychologists have proved that violent TV makes all children aggressive.’ Which study provides evidence against this?","options":["Charlton et al., who found little overall change in behaviour when TV arrived on St Helena.","Bandura, Ross and Ross, who found that children copied an adult hitting a doll.","Milgram, who found that 65% of his participants went all the way to the highest shock level.","Asch, who found that participants conformed on a third of trials."],"answer":0,"why":"Charlton et al. found little overall effect of TV on children’s behaviour, which goes against the claim."},
    {"skill":"strength","kind":"mcq","q":"Which is a strength of the St Helena study?","options":["It has high ecological validity because the children were observed in their natural playground.","It has high control because the researchers decided for themselves which of the children watched TV.","It used a large, varied sample from many different countries.","It could show exactly which TV programmes caused each act."],"answer":0,"why":"Naturalistic observation of free play in school playgrounds gives behaviour that is realistic. The researchers did not control exposure to TV."},
    {"skill":"weakness","kind":"mcq","q":"Which is a weakness of the St Helena study?","options":["It was a small, unusual community, so the results may not apply to children elsewhere.","It was done in a laboratory, so the behaviour was artificial.","It used only adults as its participants, so it cannot be used to explain children’s behaviour at all.","It only had children in one age group."],"answer":0,"why":"A remote island with a close-knit community may not represent other communities, so generalising is limited."},
    {"skill":"weakness-control","kind":"mcq","q":"Why might a natural experiment such as the St Helena study make it hard to show cause and effect?","options":["The researchers could not control other changes that happened at the same time as TV arriving.","The researchers made all the children watch violent programmes, which then affected their behaviour.","The children knew exactly what was being measured, so they changed their play.","The researchers chose only boys to take part."],"answer":0,"why":"Because TV came naturally, other changes on the island could also have affected play. Control is lower than in a lab study."},
    {"skill":"versus-bandura","kind":"mcq","q":"Which statement correctly contrasts Charlton et al. (2000) with the Bobo doll study?","options":["Charlton et al. was a natural observation with little effect; the Bobo doll study was a lab experiment showing imitation.","Charlton et al. was a lab experiment showing imitation; the Bobo doll study was a natural observation of play.","Both studies were natural experiments that showed a large increase in aggression after children watched TV.","Both studies used only adults as participants."],"answer":0,"why":"Charlton et al. observed children naturally and found little change after TV. Bandura, Ross and Ross used a controlled laboratory setting and found imitation."},
    {"skill":"common-error","kind":"mcq","q":"A student writes: ‘Charlton found that TV made children on St Helena more aggressive.’ Why is this wrong?","options":["The study found little overall change in aggression after TV arrived.","The study found that children became less aggressive after TV arrived.","The study found aggression only rose in the girls.","The study was not about television at all."],"answer":0,"why":"The main finding was little overall change in antisocial or pro-social behaviour after TV arrived."},
    {"skill":"apply-method","kind":"mcq","q":"Aisha says that Charlton et al. is a natural experiment. Which feature of the study supports this?","options":["The researchers did not decide when TV arrived; it came to the island naturally.","The researchers randomly gave TV to some homes on the island and not to the other homes.","The researchers asked the children to fill in a questionnaire.","The researchers created a play area of their own and invited the children to come and visit it."],"answer":0,"why":"In a natural experiment the change in the independent variable happens without the researcher’s intervention. Here, the arrival of TV was the natural change."},
    {"skill":"sample-link","kind":"mcq","q":"Why were children selected randomly in Charlton et al.’s study?","options":["So the sample would be more representative of the island’s children.","To make sure that every child watched the same programmes at the same time each day, to keep it fair.","To give the researchers control over the children’s behaviour.","To make sure that all of the children were aggressive."],"answer":0,"why":"Random selection gives each child in the community an equal chance of being observed, which reduces bias."},
    {"skill":"coding","kind":"mcq","q":"In Charlton et al.’s study, what was the advantage of video recording the children’s play?","options":["The behaviour could be watched again and coded carefully.","The children were more likely to show antisocial behaviour on camera.","The researchers could control the children’s behaviour.","The recording showed which programmes each child watched."],"answer":0,"why":"A recording can be replayed and coded for pro-social and antisocial acts, which makes the data more reliable."},
    {"skill":"apply-evaluate","kind":"mcq","q":"Which statement is the best evaluation of the conclusion that TV does not increase aggression?","options":["The findings come from one small remote island, so they may not apply to bigger or less supervised places.","The findings are not valid because the children were not watching TV in a laboratory under test conditions.","The findings are reliable because the island was very large.","The findings prove TV never affects anyone."],"answer":0,"why":"The main limitation is generalisability: a small community with close supervision is not typical. The other options misuse the evidence."},
    {"skill":"apply-evaluate","kind":"mcq","q":"Which evidence in a news story would <b>support</b> Charlton et al.’s conclusion that community supervision can protect children from TV violence?","options":["A report that children in a close village rarely copy violent scenes they watch.","A report that children copied a violent character at a lonely farm where no adults were watching them.","A report that adults in a large city watch violent TV.","A report that children in a big city fight a lot more than children living in a small village."],"answer":0,"why":"Supervision in a close community is the protective factor suggested by the St Helena study, so evidence of villagers not copying would support it."},
    {"skill": "apply-evaluate", "kind": "mcq", "q": "A student says: ‘Charlton et al. cannot show that TV had no effect, because children may already have seen violence in other ways.’ Which type of point is this?", "options": ["A weakness, because other influences on aggression were not controlled in a natural study.", "A strength, because natural studies control every variable.", "A strength, because the sample was big and varied.", "A weakness, because the children were observed in a laboratory."], "answer": 0, "why": "Because the researchers did not control the children’s exposure to violence from other sources, cause and effect cannot be certain."},
    {"skill": "findings-apply", "kind": "mcq", "q": "On a remote island, a teacher compares playground behaviour in the year before and the year after the first TV broadcast. She finds that the pattern of boys’ antisocial acts has not changed. Which conclusion fits Charlton et al.?", "options": ["TV did not appear to increase boys’ antisocial behaviour, though boys had been more antisocial before it.", "TV clearly increased boys’ antisocial behaviour, as the boys copied what they saw.", "TV decreased girls’ antisocial behaviour, as the girls copied what they saw.", "TV made the boys and the girls equally antisocial in the playground."], "answer": 0, "why": "Charlton et al. found little overall change after TV arrived, and boys were more antisocial than girls without any link to TV."}
  ] };

  B['PSY-CRI-04'] = { title: "Prison, community sentences and restorative justice", items: [
    {"skill":"define-recidivism","kind":"mcq","q":"What does <b>recidivism</b> mean?","options":["Reoffending after having been punished.","Committing a crime for the first time.","Being released early from a prison sentence.","Paying money to a victim after a crime."],"answer":0,"why":"Recidivism is returning to crime after a punishment. A punishment with low recidivism is one after which offenders do not reoffend."},
    {"skill":"define-prison","kind":"mcq","q":"Which statement correctly describes a <b>prison</b> sentence?","options":["A custodial punishment in which the offender loses their freedom and is removed from society.","A non-custodial punishment in which the offender stays at home and does unpaid work in the community.","A meeting in which the offender and the victim talk about the harm that was done by the crime.","A reward system in which offenders earn tokens for good behaviour."],"answer":0,"why":"Prison is custodial: the offender is held away from society. Staying in the community describes community sentencing."},
    {"skill":"prison-retributive","kind":"mcq","q":"Why is prison described as a <b>retributive</b> punishment?","options":["It aims to make the offender suffer in proportion to the crime they committed.","It aims to teach the offender new job skills so that they can use them after being released.","It aims to bring the offender and the victim face to face so that they can talk about the crime.","It aims to change the offender’s beliefs about crime."],"answer":0,"why":"Retribution means punishment that fits the crime. It is about suffering for wrongdoing and not about treatment or repair."},
    {"skill":"prison-strength","kind":"mcq","q":"Which is a <b>strength</b> of prison as a punishment?","options":["It protects the public by keeping dangerous offenders away from society.","It keeps the offender close to their family and friends, so that they can support them throughout.","It always treats the causes of the offender’s crimes.","It lets the victim tell the offender how the crime felt."],"answer":0,"why":"Removing offenders from society protects the public while they are inside. Family links, treatment and meeting victims are features of other approaches."},
    {"skill":"prison-weakness","kind":"mcq","q":"Which is a <b>weakness</b> of prison?","options":["Offenders may learn more about crime from other prisoners and reoffend.","Offenders are allowed to keep their jobs while they serve their sentence.","Offenders are kept away from other offenders at all times.","Offenders are not removed from the community in which they offended."],"answer":0,"why":"High reoffending and learning crime from other prisoners are key weaknesses. Keeping jobs describes community sentencing."},
    {"skill":"define-community","kind":"mcq","q":"Which statement correctly describes a <b>community sentence</b>?","options":["A non-custodial punishment in which the offender stays in the community and does unpaid work or follows a curfew.","A custodial punishment in which the offender is locked in a cell away from the community.","A meeting in which the offender and the victim agree how to make amends.","A punishment in which the offender pays a fine and nothing else."],"answer":0,"why":"Community sentences are non-custodial and include unpaid work or other requirements, such as a curfew."},
    {"skill":"community-strength","kind":"mcq","q":"Which is a <b>strength</b> of community sentences?","options":["Offenders keep their jobs and family links and avoid the influence of other prisoners.","Offenders are kept away from the public for the whole of their sentence, so nobody is put at risk.","Offenders face their victims and must listen to their experience.","The public always see them as a harsh enough punishment for any crime."],"answer":0,"why":"Staying in the community keeps stabilising factors such as work and family and avoids contact with hardened offenders."},
    {"skill":"community-weakness","kind":"mcq","q":"Which is a <b>weakness</b> of community sentences?","options":["They may be seen as a soft option and do not remove offenders from the public.","They always cost more than prison sentences.","They lead offenders to learn more about crime from other prisoners who have been there longer.","They need victims to agree to meet the offender."],"answer":0,"why":"Community sentences may be seen as a soft option, and offenders remain in the community, so the public is not protected in the same way as in prison."},
    {"skill":"define-restorative","kind":"mcq","q":"Which statement correctly describes <b>restorative justice</b>?","options":["The victim and offender meet so the offender understands the harm and can make amends.","The offender is removed from society for a fixed number of years.","The offender does unpaid work in the community and may have to follow a curfew every night.","The offender is punished with a rule that takes away a privilege."],"answer":0,"why":"Restorative justice brings the victim and offender together to understand the effects of the crime and repair harm."},
    {"skill":"restorative-strength","kind":"mcq","q":"Which is a <b>strength</b> of restorative justice?","options":["It can increase the offender’s empathy and the victim’s satisfaction.","It keeps the public safe by removing offenders from society.","It is suitable for every type of crime and offender.","It can go ahead without the victim or the offender agreeing to take part."],"answer":0,"why":"Meeting the victim can help offenders feel empathy and victims feel heard, which may reduce reoffending."},
    {"skill":"restorative-weakness","kind":"mcq","q":"Which is a <b>weakness</b> of restorative justice?","options":["It needs both the victim and offender to agree, and may not suit serious crimes.","It means the offender loses their freedom and cannot go to work or see their family at all.","It brings the offender into contact with other offenders.","It is too short a punishment to count as a sentence."],"answer":0,"why":"Restorative justice only works if both sides take part voluntarily, so it cannot be used in every case."},
    {"skill":"apply-restorative","kind":"mcq","q":"Two teenagers, Omar and Kai, spray graffiti on a shop. They then meet the shop owner, who explains how much cleaning cost and how worried her staff felt. Omar apologises and offers to help repaint. Which punishment is this?","options":["Restorative justice, because the offenders meet the victim and make amends.","A community sentence, because the offenders stay in the community.","A prison sentence, because the offenders are held to account for what they have done to the shop.","A punishment based on tokens, because the offenders earn a reward."],"answer":0,"why":"The meeting between offender and victim and the offer to repair the harm define restorative justice. Unpaid work ordered by a court would be a community sentence."},
    {"skill":"apply-community","kind":"mcq","q":"A court orders Dani, 19, who stole from a shop for the first time, to do 80 hours of unpaid litter-picking and stay at home between 8 pm and 6 am for three months. Which punishment is this?","options":["A community sentence, because Dani stays in the community and must do unpaid work and a curfew.","Restorative justice, because Dani will meet the shop owner.","A prison sentence, because Dani’s freedom is limited by a curfew.","A restorative sentence, because Dani is doing something good for other people in the community."],"answer":0,"why":"Unpaid work and a curfew are typical community sentence requirements. Dani is not in custody, so it is not a prison sentence."},
    {"skill":"apply-prison","kind":"mcq","q":"A man who has attacked several people is sentenced to six years in a secure unit. He cannot leave and is separated from his family. Which punishment is this, and what is its main strength for the public?","options":["A prison sentence, which protects the public while he is held away from society.","A community sentence, which lets him keep his job.","Restorative justice, which makes him meet his victims.","A prison sentence, which is mainly aimed at treating his crime-related problems."],"answer":0,"why":"He loses his freedom, so it is prison (custodial). While inside he cannot harm the public. Treatment is not the main purpose of prison."},
    {"skill":"apply-weakness","kind":"mcq","q":"Ben, 22, served a short prison sentence for theft and shared a cell with a man who taught him how to break into cars. He offended again within a month of release. Which weakness of prison does this show?","options":["Offenders may learn more about crime from other prisoners, leading to reoffending.","Prison keeps offenders in regular contact with their families and with the community outside.","Prison depends on the victim agreeing to meet the offender.","Prison allows offenders to carry out unpaid work."],"answer":0,"why":"Ben learned criminal methods from another prisoner and reoffended, which is a key weakness of prison."},
    {"skill":"apply-strength","kind":"mcq","q":"Sofia, 17, is given a community sentence. She keeps her college place and lives at home with her parents while completing unpaid work. Which strength of community sentencing does this show?","options":["She keeps her education and family links and avoids contact with experienced offenders.","She is kept away from the public for the whole of her sentence and so she cannot reoffend.","She understands the harm done because she has met the victim.","She is punished more severely than she would be in prison."],"answer":0,"why":"Community sentences keep education, work and family links. Staying in the community does not protect the public in the way that custody does."},
    {"skill":"prison-vs-community","kind":"mcq","q":"Which pair correctly distinguishes prison from community sentencing?","options":["Prison removes the offender from society, whereas community sentencing keeps them in it.","Prison brings victims and offenders together, whereas community sentencing keeps them apart.","Prison involves unpaid work, whereas community sentencing involves custody.","Prison is non-custodial, whereas community sentencing is custodial."],"answer":0,"why":"Prison is custodial and takes the offender out of society, and community sentencing is non-custodial."},
    {"skill":"community-vs-restorative","kind":"mcq","q":"A student says that restorative justice is the same as a community sentence. Which reply is correct?","options":["They differ: restorative justice is a victim–offender meeting, whereas community sentencing involves requirements like unpaid work.","They are the same because both keep the offender out of prison.","They differ: community sentencing involves meeting the victim, whereas restorative justice involves custody and a cell.","They are the same because both depend on both sides agreeing."],"answer":0,"why":"Restorative justice is built around victim-offender contact and amends. Community sentencing is a court-ordered set of requirements, not a meeting."},
    {"skill":"link-reoffending","kind":"mcq","q":"Which is the best way to evaluate a punishment in terms of reoffending?","options":["Explain how it might make offenders more or less likely to commit crime again.","Describe how long the punishment lasts and what the offender does while it is in force.","Say how many offenders are given the punishment each year.","List the places where the punishment takes place."],"answer":0,"why":"Evaluation of punishments should link strengths and weaknesses to recidivism, such as learning crime in prison or empathy from restorative justice."},
    {"skill":"nine-mark-weighing","kind":"mcq","q":"In an extended answer on whether a prison sentence is the best punishment for a young first-time offender, which approach earns the most credit?","options":["Weigh protection of the public against the risk of reoffending, link to the offender, then give a justified judgement.","List as many facts about prison as possible without applying any of them to the young offender.","Describe only the strengths of prison and say it is best.","Give a judgement at the start and repeat it three times."],"answer":0,"why":"High-level answers apply points to the person, weigh both sides with reference to reoffending and give a reasoned conclusion."},
    {"skill":"apply-judgement","kind":"mcq","q":"Which is the best supported judgement about a first-time shoplifter aged 16?","options":["A community sentence or restorative justice may be better than prison because it avoids contact with experienced offenders.","Prison is always the best punishment for young offenders, because it makes offenders suffer for their crimes.","No punishment is needed, because the crime was small.","Restorative justice must be used, because it works for every offender."],"answer":0,"why":"A judgement should be supported with reasons linked to reoffending and the offender. The other statements use absolute claims that are not justified."},
    {"skill": "apply-punishment", "kind": "mcq", "q": "Which situation is the best example of a <b>custodial</b> punishment?", "options": ["A man is sent to a secure prison for five years and cannot go home.", "A woman is ordered to do 100 hours of unpaid gardening in her town.", "A teenager meets the person he robbed and agrees to pay for the damage.", "A driver is ordered to stay at home between 9 pm and 6 am."], "answer": 0, "why": "Custodial means the offender is held in a place such as prison. The other examples are served in the community or involve a meeting with the victim."},
    {"skill": "define-recidivism-apply", "kind": "mcq", "q": "Out of 100 offenders released from a scheme, 20 committed another crime within a year. Which statement about recidivism is correct?", "options": ["Recidivism is the reoffending of those 20, so 80 did not reoffend.", "Recidivism is the 80 who did not reoffend.", "Recidivism is the total of 100 who were released.", "Recidivism is the length of the original punishment."], "answer": 0, "why": "Recidivism means reoffending after being punished. Twenty of the 100 reoffended, so the other 80 did not."}
  ] };

  B['PSY-CRI-01'] = { title: "Operant conditioning: rewards and punishments that shape crime", items: [
    {"skill":"define-operant","kind":"mcq","q":"According to operant conditioning (Skinner), what shapes behaviour?","options":["The consequences that follow the behaviour.","The behaviour of role models that are watched.","The personality traits that are inherited.","The thoughts that come before the behaviour."],"answer":0,"why":"Operant conditioning says behaviour is learned through consequences: rewards make it more likely, punishments make it less likely."},
    {"skill":"define-pos-reinforcement","kind":"mcq","q":"What is <b>positive reinforcement</b>?","options":["Something pleasant is added after a behaviour, so the behaviour is more likely to be repeated.","Something unpleasant is removed after a behaviour, so the behaviour is more likely to be repeated.","Something unpleasant is added after a behaviour, so the behaviour is less likely to be repeated.","Something pleasant is removed after a behaviour, so the behaviour is less likely to be repeated."],"answer":0,"why":"‘Positive’ means something is added, and ‘reinforcement’ means the behaviour becomes more likely. It does not mean the outcome is good."},
    {"skill":"define-neg-reinforcement","kind":"mcq","q":"What is <b>negative reinforcement</b>?","options":["Something unpleasant is taken away after a behaviour, so the behaviour is more likely to be repeated.","Something pleasant is added after a behaviour, so the behaviour is more likely to be repeated.","Something unpleasant is added after a behaviour, so the behaviour is less likely to be repeated.","Something pleasant is taken away after a behaviour, so the behaviour is then less likely to be repeated in future."],"answer":0,"why":"Negative = taken away. Reinforcement = behaviour more likely. Negative reinforcement is not a punishment."},
    {"skill":"define-pos-punishment","kind":"mcq","q":"What is <b>positive punishment</b>?","options":["Something unpleasant is added after a behaviour, so it becomes less likely.","Something pleasant is added after a behaviour, so it becomes more likely.","Something unpleasant is taken away after a behaviour, so it becomes more likely.","Something pleasant is taken away after a behaviour, so it becomes less likely."],"answer":0,"why":"‘Positive’ means added and ‘punishment’ means the behaviour becomes less likely, as with a fine."},
    {"skill":"define-neg-punishment","kind":"mcq","q":"What is <b>negative punishment</b>?","options":["Something pleasant is taken away after a behaviour, so it becomes less likely.","Something unpleasant is taken away after a behaviour, so it becomes more likely.","Something unpleasant is added after a behaviour, so it becomes less likely.","Something pleasant is added after a behaviour, so it becomes more likely."],"answer":0,"why":"‘Negative’ means taken away and ‘punishment’ means less likely, as when someone loses a driving licence."},
    {"skill":"apply-pos-reinforce","kind":"mcq","q":"Kit steals designer clothes from a shop and sells them for a large sum of money. He steals again the next week. Which term explains why he repeats the crime?","options":["Positive reinforcement, because the money is a pleasant consequence that was added.","Negative reinforcement, because something unpleasant was taken away from Kit after the crime.","Positive punishment, because Kit gets away without being caught.","Negative punishment, because Kit is taking something away from the shop that does not belong to him."],"answer":0,"why":"Money is added after the crime and Kit repeats the behaviour, which is positive reinforcement."},
    {"skill":"apply-neg-reinforce","kind":"mcq","q":"Hana is being bullied and has no money for lunch. When she steals a sandwich, her hunger stops. She steals food again the next day. Which term explains why she repeats the crime?","options":["Negative reinforcement, because the unpleasant hunger is taken away.","Positive reinforcement, because she was given extra food.","Positive punishment, because stealing the sandwich led to something unpleasant being added for her.","Negative punishment, because she was given nothing to eat until she had stolen the sandwich."],"answer":0,"why":"Something unpleasant (hunger) is removed after the behaviour, making it more likely to be repeated. That is negative reinforcement."},
    {"skill":"apply-pos-punish","kind":"mcq","q":"After being caught speeding, Jamal is given a large fine. He now keeps to the speed limit. Which term explains the change in his behaviour?","options":["Positive punishment, because something unpleasant (a fine) was added.","Negative punishment, because something pleasant was taken away.","Positive reinforcement, because something pleasant was added.","Negative reinforcement, because something unpleasant was taken away from Jamal after the speeding."],"answer":0,"why":"A fine is an unpleasant consequence added after the behaviour, and speeding becomes less likely."},
    {"skill":"apply-neg-punish","kind":"mcq","q":"A teenager who shoplifts has his mobile phone taken away by his parents for a month. He stops shoplifting. Which term explains the change in his behaviour?","options":["Negative punishment, because something pleasant (his phone) was taken away.","Positive punishment, because something unpleasant was added.","Negative reinforcement, because something unpleasant was taken away from him when the month ended.","Positive reinforcement, because the phone was given back later."],"answer":0,"why":"Removing the phone takes away something pleasant, and the shoplifting becomes less likely."},
    {"skill":"apply-neg-punish","kind":"mcq","q":"Marta is convicted of drink-driving and loses her driving licence for a year. Which operant condition is this?","options":["Negative punishment, because something she values is taken away.","Positive punishment, because the court has added a penalty that makes drink-driving less likely.","Negative reinforcement, because she is now safer on the road and so will take fewer risks.","Positive reinforcement, because she will walk more."],"answer":0,"why":"Her licence (something pleasant) is removed, and the behaviour is intended to become less likely. This is negative punishment."},
    {"skill":"distinguish","kind":"mcq","q":"Which pair correctly matches the terms to the examples?","options":["A fine for littering is positive punishment; getting out of a boring lesson by misbehaving is negative reinforcement.","A fine for littering is negative punishment; getting out of a boring lesson by misbehaving is positive reinforcement.","A fine for littering is positive reinforcement; getting out of a boring lesson by misbehaving is negative punishment.","A fine for littering is negative reinforcement; getting out of a boring lesson by misbehaving is positive punishment."],"answer":0,"why":"A fine is added and unpleasant, so it is positive punishment. Escaping something unpleasant (a boring lesson) makes misbehaving more likely, so it is negative reinforcement."},
    {"skill":"common-error","kind":"mcq","q":"A student says: ‘Negative reinforcement is a type of punishment.’ What is wrong with this?","options":["Negative reinforcement makes a behaviour more likely, whereas punishment makes it less likely.","Negative reinforcement adds something pleasant, whereas punishment takes something unpleasant away.","Negative reinforcement is a punishment for a crime and always means a prison sentence.","Negative reinforcement only applies to learning from role models."],"answer":0,"why":"Reinforcement always increases the chance of a behaviour. Negative simply means something is taken away."},
    {"skill":"common-error","kind":"mcq","q":"A student writes: ‘Positive reinforcement means the result is good for society.’ What is wrong with this?","options":["‘Positive’ means something is added; it can be a reward for a crime.","‘Positive’ means that the behaviour becomes less likely to happen again in the future.","‘Positive’ means that something is taken away from the person after the behaviour.","‘Positive’ only applies to behaviour that is legal."],"answer":0,"why":"In operant conditioning ‘positive’ and ‘negative’ describe adding or removing something, not whether the result is good."},
    {"skill":"define-primary","kind":"mcq","q":"Which is a <b>primary reinforcer</b>?","options":["Food, because it meets a basic biological need.","Money, because it can be spent on food and other things that a person needs.","A token, because it can be swapped for a reward in a token economy programme.","A gift voucher, because it can be exchanged in a shop."],"answer":0,"why":"Primary reinforcers meet basic biological needs directly, such as food, warmth and sleep."},
    {"skill":"define-secondary","kind":"mcq","q":"Which is a <b>secondary reinforcer</b>?","options":["Money, because it has no value itself but can be swapped for a primary reinforcer.","Sleep, because it is a basic need which a person has, and it is satisfied directly.","Warmth, because it satisfies a basic need directly and does not need to be swapped.","A drink of water, because it meets a basic need directly."],"answer":0,"why":"Secondary reinforcers such as money or tokens only have value because they can be swapped for primary reinforcers."},
    {"skill":"apply-primary-secondary","kind":"mcq","q":"A gang leader pays a young member £50 each time he steals a car. The member spends the money on food and a place to sleep. Which description is correct?","options":["The £50 is a secondary reinforcer because it is swapped for primary reinforcers.","The £50 is a primary reinforcer because it meets his basic needs for food and a bed.","The food and bed are secondary reinforcers because they have to be paid for with money.","The £50 is a positive punishment because it has been added."],"answer":0,"why":"Money has no value in itself, but can be exchanged for food and a bed, which are primary reinforcers."},
    {"skill":"primary-secondary","kind":"multi","q":"Which of these are <b>primary</b> reinforcers? Select all that apply.","options":["Food","Warmth","Sleep","Cash","Tokens"],"answers":[0,1,2],"why":"Food, warmth and sleep meet basic biological needs directly. Cash and tokens are secondary reinforcers."},
    {"skill":"strength","kind":"mcq","q":"Which is a strength of operant conditioning as an explanation of crime?","options":["It explains why crime that pays, such as robbery, continues.","It explains why people commit crimes that bring them no reward of any kind at all.","It explains the way that personality is inherited and then affects the risk of crime.","It explains how crime is learned by watching a model."],"answer":0,"why":"Crime that brings rewards is reinforced and repeated. Crimes without reward, biology and observational learning are not explained by it."},
    {"skill":"weakness","kind":"mcq","q":"Which is a weakness of operant conditioning as an explanation of crime?","options":["It ignores biological factors and cannot explain crimes with no obvious reward.","It cannot explain why people repeat a crime for which they were paid again and again.","It ignores the role that rewards and punishments play in how behaviour is learned.","It does not explain why a fine can stop speeding."],"answer":0,"why":"A weakness is that it ignores biology and cannot explain crimes with no clear reward, such as a violent act of anger."},
    {"skill":"apply-weakness","kind":"mcq","q":"Lee often starts fights outside bars. He is never paid for it, nobody applauds him, and he is often hurt. Which criticism of operant conditioning does Lee’s case show?","options":["It cannot explain crimes that have no obvious reward.","It cannot explain why people respond to fines.","It cannot explain why the money in a robbery encourages repeats.","It cannot explain why a teenager keeps stealing when he is paid."],"answer":0,"why":"Lee’s fights bring him no clear reward, so operant conditioning struggles to explain them."},
    {"skill":"apply-two-terms","kind":"mcq","q":"Tess takes money from a till and uses it to buy a game she wants. Her mother then bans her from going out for two weeks. Which pair of operant terms fits?","options":["Positive reinforcement for taking the money; negative punishment for the ban.","Negative reinforcement for taking the money; positive punishment for the ban.","Positive punishment for taking the money; negative reinforcement for the ban.","Negative punishment for taking the money; positive reinforcement for the ban."],"answer":0,"why":"The game is a pleasant thing added, so positive reinforcement. Losing the freedom to go out is something pleasant taken away, so negative punishment."},
    {"skill":"predict","kind":"mcq","q":"Which statement is the best summary of what will happen to Gus’s behaviour in the future when he is paid £50 for each bike he steals?","options":["He is likely to steal more bikes, because the payment reinforces the behaviour.","He is likely to steal fewer bikes, because the payment punishes the behaviour.","His behaviour is unlikely to change, because the payment is a secondary reinforcer.","He will steal bikes only when he sees a role model do so."],"answer":0,"why":"A reward after a behaviour makes it more likely. Secondary reinforcers still reinforce behaviour."}
  ] };

  B['PSY-CRI-03'] = { title: "Eysenck's criminal personality", items: [
    {"skill":"theory-basis","kind":"mcq","q":"What did Eysenck (1964) propose about personality?","options":["It is largely inherited and based on the nervous system.","It is mainly learned by watching and copying role models.","It is shaped by the rewards and punishments a person receives.","It is formed by the roles people take on in a group."],"answer":0,"why":"Eysenck’s theory is biological: personality types come mainly from the inherited nervous system, not from learning."},
    {"skill":"define-extraversion","kind":"mcq","q":"Which person best fits a high score on <b>extraversion</b>?","options":["Someone who is sociable, impulsive and seeks excitement.","Someone who is anxious, moody and easily upset by small things that go wrong.","Someone who is cold, hostile and lacks empathy.","Someone who is calm, quiet and who prefers to spend most of their time alone."],"answer":0,"why":"Extraverts are sociable, impulsive and seek excitement. The other descriptions fit neuroticism, psychoticism and introversion."},
    {"skill":"define-neuroticism","kind":"mcq","q":"Which person best fits a high score on <b>neuroticism</b>?","options":["Someone who is anxious, moody and emotionally unstable.","Someone who is sociable, lively and who is always looking for more excitement.","Someone who is cold, aggressive and lacks empathy.","Someone who stays calm and emotionally stable."],"answer":0,"why":"High neuroticism means anxiety, moodiness and emotional instability. Stability is the opposite end of the dimension."},
    {"skill":"define-psychoticism","kind":"mcq","q":"Which person best fits a high score on <b>psychoticism</b>?","options":["Someone who is cold, hostile and aggressive and lacks empathy.","Someone who is anxious, moody and worries a lot.","Someone who is sociable, outgoing and impulsive.","Someone who has a serious mental illness and loses touch with reality."],"answer":0,"why":"In Eysenck’s theory, psychoticism is a personality trait of coldness, hostility and lack of empathy. It does not mean having a mental illness."},
    {"skill":"define-introversion","kind":"mcq","q":"Which person is closest to the <b>introvert</b> end of the extraversion–introversion dimension?","options":["Someone who is quiet, reserved and does not seek excitement.","Someone who is sociable, impulsive and who always seeks out excitement and risk.","Someone who is cold, hostile and aggressive.","Someone who is anxious and who is emotionally unstable most of the time."],"answer":0,"why":"Introversion is the opposite of extraversion: quiet, reserved people who do not look for thrills."},
    {"skill":"criminal-personality","kind":"mcq","q":"According to Eysenck, which personality profile is most likely to be linked to criminal behaviour?","options":["High scores on psychoticism, extraversion and neuroticism.","Low scores on psychoticism, extraversion and neuroticism.","High on introversion, low on neuroticism and low on psychoticism.","High on extraversion only, with low scores on the other two dimensions."],"answer":0,"why":"Eysenck proposed that the criminal personality scores high on all three dimensions: P, E and N."},
    {"skill":"common-error","kind":"mcq","q":"A student writes: ‘Eysenck said criminals are introverts.’ What is wrong with this?","options":["Eysenck said criminals tend to score high on extraversion, not introversion.","Eysenck said criminals tend to score low on neuroticism, which means that they are calm.","Eysenck said criminals are all stable and calm and rarely act on impulse at all.","Eysenck said introverts commit most crimes."],"answer":0,"why":"Eysenck linked criminality to high extraversion (together with high neuroticism and psychoticism)."},
    {"skill":"apply-E","kind":"mcq","q":"Dario loves danger and often breaks into empty buildings for the thrill of it. He gets bored easily and is always looking for the next adventure. Which of Eysenck’s dimensions does this best show?","options":["Extraversion, because he is impulsive and seeks excitement.","Neuroticism, because he is anxious and moody.","Psychoticism, because he is cold and has no empathy.","Introversion, because he spends a lot of his free time alone, away from other people."],"answer":0,"why":"Thrill-seeking and impulsiveness are typical of extraversion."},
    {"skill":"apply-P","kind":"mcq","q":"Wren set fire to a neighbour’s shed after an argument. She showed no remorse and said the neighbour deserved it. Which of Eysenck’s dimensions does this best show?","options":["Psychoticism, because she is hostile and lacks empathy.","Extraversion, because she is sociable and talkative.","Neuroticism, because she is anxious about what she has done.","Introversion, because she is quiet and calm."],"answer":0,"why":"Hostility, aggression and a lack of empathy or remorse are signs of psychoticism."},
    {"skill":"apply-N","kind":"mcq","q":"Cal gets extremely anxious when he is short of money. He panics, loses his temper quickly and has stolen from friends in a state of worry. Which of Eysenck’s dimensions does this best show?","options":["Neuroticism, because he is anxious and emotionally unstable.","Extraversion, because he seeks excitement and is always looking out for new thrills.","Psychoticism, because he lacks empathy.","Stability, because he stays calm under pressure and never panics about money."],"answer":0,"why":"Anxiety, moodiness and emotional instability are characteristic of neuroticism."},
    {"skill":"nervous-system","kind":"mcq","q":"How did Eysenck explain why extraverts seek excitement?","options":["Their nervous system is under-aroused, so they look for stimulation.","Their nervous system is over-aroused, so they avoid stimulation as much as they can.","They have learned from role models that excitement is rewarded and then copy that.","They have been punished when they were quiet as children."],"answer":0,"why":"Extraverts’ nervous systems are under-aroused, so they seek excitement to raise their arousal. This is a biological explanation."},
    {"skill":"conditioning","kind":"mcq","q":"Why might extraverts learn less from punishment, according to Eysenck?","options":["They are harder to condition, so punishment has less effect on them.","They are easier to condition, so punishment is too strong for them and they stop.","They copy the behaviour of the person who punishes them, so they repeat the crime.","They are rewarded by the punishment itself."],"answer":0,"why":"Eysenck thought extraverts are harder to condition, so they do not learn to avoid crime in the same way as introverts."},
    {"skill":"apply-conditioning","kind":"mcq","q":"A teacher gives the same detention to two pupils who both broke a window. Zed, an extreme extravert, breaks windows again within a week; Ila, an introvert, never does. Which idea from Eysenck explains this?","options":["Extraverts are harder to condition, so Zed learns less from the punishment.","Zed is more easily conditioned than Ila, so he copies the detention he was given.","Ila has high psychoticism, so she lacks empathy.","Zed has an internal locus of control, which means that he ignores any punishment."],"answer":0,"why":"Eysenck argued that extraverts are less affected by punishment because they are harder to condition."},
    {"skill":"apply-profile","kind":"mcq","q":"A researcher tests three adults: Pat (high P, high E, high N), Quin (low P, low E, low N) and Ray (high E only). Based on Eysenck’s theory, who is most likely to commit crime?","options":["Pat, because the criminal personality scores high on all three dimensions.","Quin, because low scores on all three are linked to impulsive crime in adults.","Ray, because extraversion alone causes crime.","All three equally, because personality is not linked to crime in Eysenck’s theory."],"answer":0,"why":"Eysenck proposed a high score on all three of P, E and N predisposes people to crime."},
    {"skill":"support","kind":"mcq","q":"Which finding would <b>support</b> Eysenck’s theory?","options":["Young offenders score higher than non-offenders on P, E and N.","Non-offenders score higher than offenders on psychoticism, extraversion and neuroticism.","Offenders and non-offenders score the same on psychoticism, extraversion and neuroticism.","Offenders score higher than non-offenders on introversion only."],"answer":0,"why":"Studies comparing offenders with non-offenders that find higher P, E and N scores in offenders are supportive evidence."},
    {"skill":"weakness-learning","kind":"mcq","q":"Which is a weakness of Eysenck’s theory?","options":["It ignores learning and social factors, such as the influence of family.","It cannot be tested because it makes no predictions about how personality is measured.","It pays too much attention to the role of rewards.","It argues that everyone has the same personality."],"answer":0,"why":"Eysenck’s theory focuses on inherited biology and says little about learning from family and peers."},
    {"skill":"weakness-selfreport","kind":"mcq","q":"Why is it a weakness that Eysenck’s personality traits are measured with questionnaires?","options":["People may not answer honestly, so the scores may not be accurate.","Questionnaires are not able to measure any personality traits, however honest the answers are.","Questionnaires can only be answered by children.","Questionnaires are always too long to complete."],"answer":0,"why":"Questionnaires rely on self-report. Offenders may not answer truthfully, which reduces validity."},
    {"skill":"apply-alternative","kind":"mcq","q":"Rosa’s older brothers and father all steal cars. Rosa starts stealing cars too. Which explanation would be a fair criticism of Eysenck’s theory for her case?","options":["She may have learned to offend from family, which the theory ignores.","She must have a high score on introversion, which the theory does not take into account.","She has been punished too severely, which the theory ignores.","She has an external locus of control, which the theory ignores."],"answer":0,"why":"Social learning from her family is an alternative explanation that Eysenck’s biological theory does not consider."},
    {"skill":"strength-research","kind":"mcq","q":"Which is a strength of Eysenck’s theory as an explanation of criminality?","options":["It has research support from studies finding higher P, E and N scores in offenders.","It explains how crime is learned from watching role models.","It is supported by evidence that rewards always lead to a crime being repeated by anyone.","It accounts for the influence of family and friends."],"answer":0,"why":"Studies comparing delinquents with non-delinquents often find higher P, E and N scores, which supports the theory."},
    {"skill":"dimension-pair","kind":"mcq","q":"Which pair correctly links the personality dimension to its description?","options":["Neuroticism – anxious and moody; psychoticism – cold and hostile.","Neuroticism – cold and hostile; psychoticism – anxious and moody.","Extraversion – anxious and moody; neuroticism – sociable and impulsive.","Psychoticism – sociable and impulsive; extraversion – cold and hostile."],"answer":0,"why":"Neuroticism is about anxiety and emotional instability. Psychoticism is about coldness and hostility. Extraversion is about sociability and thrill-seeking."},
    {"skill":"apply-mixed","kind":"mcq","q":"Ivy is always the centre of the party, will try any dare, and is unmoved by other people’s feelings. Which two dimensions does this most clearly suggest she scores high on?","options":["Extraversion and psychoticism.","Neuroticism and introversion.","Introversion and psychoticism.","Neuroticism and stability."],"answer":0,"why":"Being the centre of attention and daring suggests extraversion, and indifference to others’ feelings suggests psychoticism."},
    {"skill":"not-eysenck","kind":"mcq","q":"Which of these is <b>not</b> part of Eysenck’s explanation of why some people become offenders?","options":["Offenders learn crime by copying role models they admire.","Personality is largely inherited and based on the nervous system.","Extraverts are harder to condition, so they learn less from punishment.","Offenders tend to score high on neuroticism."],"answer":0,"why":"Copying role models is social learning theory. Eysenck’s theory is biological: inherited nervous system differences, harder conditioning in extraverts and high P, E and N scores."},
    {"skill":"apply-N-E","kind":"mcq","q":"Kai steals for the thrill and is the loudest person in his group. After each theft he cannot sleep for worry that he will be caught. Which two dimensions does this most clearly suggest he scores high on?","options":["Extraversion and neuroticism.","Introversion and psychoticism.","Psychoticism and stability.","Introversion and neuroticism."],"answer":0,"why":"Thrill-seeking and being the loudest in the group suggest extraversion, and constant worry and sleeplessness suggest neuroticism."}
  ] };

  B['PSY-CRI-02'] = { title: "Social learning theory and the Bobo doll study", items: [
    {"skill":"define-slt","kind":"mcq","q":"According to social learning theory (Bandura), how is behaviour, including crime, learned?","options":["By watching and copying other people.","By the consequences that follow the learner’s own behaviour.","By inheriting a personality type from parents.","By obeying direct orders from an authority figure."],"answer":0,"why":"Social learning theory says people learn by observing models and imitating them. Learning from your own consequences is operant conditioning."},
    {"skill":"define-role-model","kind":"mcq","q":"Which person is most likely to be a strong <b>role model</b> for a teenager?","options":["A high-status older teenager of the same sex whom he looks up to.","A stranger he never sees and does not know, who lives in another town and is a lot older.","A much younger child he rarely meets.","A person he strongly dislikes."],"answer":0,"why":"Role models are people we look up to, often similar to us, of high status or of the same sex. Identification with them makes copying more likely."},
    {"skill":"define-identification","kind":"mcq","q":"What is <b>identification</b> in social learning theory?","options":["Seeing yourself as similar to a model and wanting to be like them.","Being told what to do by a model who has the authority to give you orders.","Remembering the order of the events that you have observed another person carry out.","Being rewarded by a model after you copy them."],"answer":0,"why":"Identification happens when the observer relates to the model, which makes imitation more likely."},
    {"skill":"define-vicarious","kind":"mcq","q":"What is <b>vicarious reinforcement</b>?","options":["Seeing someone else rewarded for a behaviour, which makes you more likely to copy it.","Being given a reward yourself for a behaviour you have copied from a model.","Seeing someone else punished for a behaviour, which then makes you copy it.","Having something unpleasant taken away after you act."],"answer":0,"why":"Vicarious reinforcement is learning from the rewards that other people receive, without being rewarded yourself."},
    {"skill":"apply-vicarious","kind":"mcq","q":"Ella sees a classmate boast that she was given a free phone after shouting at a shop assistant. Ella then shouts at a shop assistant herself. Which concept explains why she copied?","options":["Vicarious reinforcement, because she saw someone else being rewarded.","Positive reinforcement, because Ella herself was given a reward by the shop assistant.","Negative punishment, because the shop assistant lost something when Ella shouted.","Deindividuation, because Ella lost her sense of identity."],"answer":0,"why":"Ella was not rewarded herself, so it is vicarious reinforcement."},
    {"skill":"processes","kind":"mcq","q":"Which list correctly gives the four processes of observational learning?","options":["Attention, retention, reproduction and motivation.","Attention, obedience, conformity and reward.","Retention, punishment, motivation and identification.","Reproduction, extraversion, attention and reward."],"answer":0,"why":"To copy a model, an observer must pay attention, keep the behaviour in memory (retention), be able to reproduce it and be motivated to do so."},
    {"skill":"apply-attention","kind":"mcq","q":"Mo watches an older boy he admires carry out a break-in in a computer game. Later, Mo describes how the older boy did it and copies the technique on a real shed. Which process is shown by Mo remembering how it was done?","options":["Retention, because Mo has stored the behaviour in memory.","Attention, because Mo is watching the older boy while he carries out the break-in.","Motivation, because Mo wants to impress the older boy that he admires so much.","Reproduction, because Mo is able to carry out the act himself on the real shed."],"answer":0,"why":"Retention is keeping what was observed in memory so that it can be copied later."},
    {"skill":"apply-reproduction","kind":"mcq","q":"Lara watches her cousin hot-wire a car. She has seen exactly how he does it and wants to copy him, but she does not have the physical skill to do it. Which process of observational learning is missing?","options":["Reproduction, because she cannot carry out what she saw.","Attention, because she did not watch her cousin while he was hot-wiring the car.","Retention, because she cannot remember what she saw her cousin do to the car.","Motivation, because she does not want to copy her cousin in any way at all."],"answer":0,"why":"Reproduction requires the ability to physically perform the behaviour. Lara paid attention, remembers and wants to copy it."},
    {"skill":"bandura-sample","kind":"mcq","q":"Which describes the sample in the Bobo doll study (Bandura, Ross and Ross, 1961)?","options":["72 children aged about 3 to 5 from a university nursery.","72 adult volunteers who were recruited from a university campus and paid for taking part.","24 children aged about 11 to 13 who were taken from a local secondary school.","400 teenagers recruited by an advert."],"answer":0,"why":"The study used 72 young children, aged about 3 to 5, from a university nursery."},
    {"skill":"bandura-conditions","kind":"mcq","q":"What did the children in the Bobo doll study see?","options":["An adult acting aggressively towards a Bobo doll, an adult acting non-aggressively, or no adult (control).","Only an adult who punished children for being aggressive towards a Bobo doll in the room.","A film in which a cartoon character hit a doll, shown to the children on a screen.","An adult who was rewarded with sweets and praise for being aggressive towards a Bobo doll."],"answer":0,"why":"Children were allocated to watch an aggressive model, a non-aggressive model or no model at all."},
    {"skill":"bandura-procedure","kind":"mcq","q":"What happened to the children after they saw the model in Bandura’s study?","options":["They were mildly frustrated, then watched through a one-way mirror for 20 minutes in a room with toys.","They were given a questionnaire about how aggressive they felt.","They were sent home and observed by their teachers the next week.","They were rewarded with sweets for copying the model, and then watched for 20 minutes."],"answer":0,"why":"After being frustrated, the children were watched through a one-way mirror in a room containing toys, including a Bobo doll, for 20 minutes."},
    {"skill":"bandura-results","kind":"mcq","q":"What did Bandura, Ross and Ross find about the children who saw the aggressive model?","options":["They imitated more of the model’s hitting and shouting than children in other conditions.","They showed less aggression than the children who saw no model at all in the room.","They showed the same level of aggression as children who saw a non-aggressive model.","They only copied the model if they had been punished for being aggressive in the past."],"answer":0,"why":"Children who observed an aggressive adult imitated more of the adult’s physical and verbal aggression."},
    {"skill":"bandura-gender","kind":"mcq","q":"What did Bandura, Ross and Ross find about boys and physical aggression?","options":["Boys copied more physical aggression than girls; the male model had more influence.","Girls copied more physical aggression than boys did, and the female model had more influence.","Boys and girls copied exactly the same amount of physical aggression from every model.","Boys copied the female model more than the male model."],"answer":0,"why":"Boys showed more imitation of physical aggression, and the male model was more influential. This is consistent with identification with a same-sex model."},
    {"skill":"bandura-conclusion","kind":"mcq","q":"What is the main conclusion of the Bobo doll study?","options":["Children can learn aggressive behaviour by watching a model and imitating it.","Children are aggressive because of an inherited personality type that is linked to the nervous system.","Children only learn aggression from rewards that are given directly to the child themselves.","Children do not copy the behaviour of adults."],"answer":0,"why":"Imitation of the aggressive model showed that aggression can be learned through observation, supporting social learning theory."},
    {"skill":"apply-bandura","kind":"mcq","q":"A nursery teacher notices that after children watched a puppet show in which a puppet hit another puppet, several started hitting their toys in the same way. Which study supports this?","options":["Bandura, Ross and Ross (1961), because children imitated an aggressive model.","Charlton et al. (2000), because TV had no effect on the children’s playground behaviour on the island.","Haney, Banks and Zimbardo (1973), because roles change behaviour.","Asch (1951), because people go along with a majority."],"answer":0,"why":"Children copied the aggressive act they had observed, as in the Bobo doll study."},
    {"skill":"apply-slt","kind":"mcq","q":"Raff, 14, looks up to his older brother, who boasts that he got away with stealing from shops and was praised by his friends. Raff then starts shoplifting. Which explanation is the best?","options":["He identifies with his brother and has seen him rewarded, so he copies him.","He has been directly rewarded for stealing in the past and so he repeats the behaviour.","He has a high score on psychoticism, so he is likely to become a criminal in time.","He is obeying his brother’s instructions."],"answer":0,"why":"The brother is a role model whom Raff identifies with, and seeing his brother praised is vicarious reinforcement."},
    {"skill":"apply-slt-nottheory","kind":"mcq","q":"Which statement is a <b>social learning</b> explanation of why Mia started vandalising bus shelters?","options":["She watched older girls she admired doing it and being praised for it.","She received money each time she damaged a shelter, so she repeated it to get more.","She is always seeking thrills because her nervous system is under-aroused and she gets bored.","She was ordered to by a teacher."],"answer":0,"why":"Watching admired models being praised is observational learning with vicarious reinforcement. Money is operant conditioning and an under-aroused nervous system is Eysenck’s theory."},
    {"skill":"strength-lab","kind":"mcq","q":"Which is a strength of the Bobo doll study?","options":["It was done in a controlled setting, so other variables could be kept the same.","It was done in the children’s own homes, so the behaviour was completely natural there.","It used a very large, varied sample.","It showed that aggression is inherited from parents and is not learned from models."],"answer":0,"why":"The study took place in a laboratory with control over the model, the room and the toys, so cause and effect can be investigated."},
    {"skill":"weakness-artificial","kind":"mcq","q":"Which is a weakness of the Bobo doll study?","options":["It was artificial: the children hit a doll, not a person, so the aggression may not be real.","It was done in a natural setting, so conditions could not be controlled by the researchers at all.","It used adults only, so it cannot show how young children learn behaviour from models.","It had no control group."],"answer":0,"why":"A Bobo doll is designed to be hit, and the setting was a laboratory. This limits generalisation to real-life aggression."},
    {"skill":"weakness-ethics","kind":"mcq","q":"Which ethical concern could be raised about the Bobo doll study?","options":["Young children were deliberately frustrated and shown aggressive behaviour by an adult.","The children were given sweets as a reward for hitting the doll.","The children were left alone in a room for several hours.","The results were never shared with anyone."],"answer":0,"why":"Young children were shown aggression and frustrated, which could have caused distress or encouraged aggression."},
    {"skill":"compare-charlton","kind":"mcq","q":"How does the Charlton et al. (2000) St Helena study challenge the claim that children copy aggressive models?","options":["Children showed little overall change in aggression after TV arrived.","Children there became a lot more aggressive after television had arrived on the island.","Children there copied the television characters in their play in the school playground.","Girls became more aggressive after TV arrived."],"answer":0,"why":"Charlton et al. found little overall change in children’s behaviour after TV, which suggests that exposure to aggressive models does not always lead to imitation."},
    {"skill":"nine-mark","kind":"mcq","q":"In an extended answer applying social learning theory to a teenager who joined a gang, which paragraph would earn the most credit?","options":["It links a gang member as a role model to identification and vicarious reinforcement, then evaluates the theory.","It describes the Bobo doll procedure in great detail without mentioning the teenager or the gang.","It states that the teenager is violent because of his inherited personality and nervous system.","It lists the four processes of observational learning in a bullet list, with no mention of the teenager."],"answer":0,"why":"Top-level answers apply the theory to the person, use accurate terms and evaluate with other evidence or explanations."}
  ] };
})();
